// class axi4_ref_model

// axi4_ref_model.sv
// File        : axi4_ref_model.sv
// Description : Reference model (memory + behavior model) for the AXI4 slave DUT.
//               Models: write channel (AW+W->B), read channel (AR->R),
//               narrow-read simplification (no byte-lane shifting),
//               SLVERR stickiness, address-range checking,
//               WRAP burst constraints (len in {1,3,7,15}).
// Author      : Verification Engineer
// Date        : 2026-09-17
// Revision    : 1.0

`ifndef AXI4_REF_MODEL_SV
`define AXI4_REF_MODEL_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_ref_model extends uvm_component;

  // -----------------------------------------------------------------------
  // Memory array (32-bit words, depth = C_S_AXI_MEM_DEPTH)
  // -----------------------------------------------------------------------
  reg [31:0] mem [0:`C_S_AXI_MEM_DEPTH-1];

  // -----------------------------------------------------------------------
  // SLVERR stickiness: once SLVERR in a burst, stays SLVERR
  // -----------------------------------------------------------------------
  bit slverr_sticky;

  // -----------------------------------------------------------------------
  // Current burst tracking for stickiness
  // -----------------------------------------------------------------------
  bit [31:0]  burst_start_addr;
  bit [7:0]   burst_len;
  bit [2:0]   burst_size;
  bit [1:0]   burst_type;
  bit         burst_in_progress;

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_component_utils(axi4_ref_model)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_ref_model", uvm_component parent);
    super.new(name, parent);
    slverr_sticky = 1'b0;
    burst_in_progress = 1'b0;
    `uvm_info("REF", "axi4_ref_model constructed", UVM_MEDIUM)
  endfunction

  // -----------------------------------------------------------------------
  // Build phase
  // -----------------------------------------------------------------------
  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    // Initialize memory to 0
    mem = '{default: '0};
    `uvm_info("REF", "Memory initialized to 0", UVM_LOW)
  endfunction

  // -----------------------------------------------------------------------
  // Reset the reference model (called on reset assertion)
  // -----------------------------------------------------------------------
  function void reset();
    mem = '{default: '0};
    slverr_sticky = 1'b0;
    burst_in_progress = 1'b0;
    `uvm_info("REF", "Reference model reset", UVM_LOW)
  endfunction

  // -----------------------------------------------------------------------
  // Predict B response for a write transaction
  // -----------------------------------------------------------------------
  function bit [1:0] predict_b_resp(axi4_seq_item tx);
    bit [31:0] addr = tx.ax_addr;
    bit [7:0]  len  = tx.ax_len;
    bit [2:0]  size = tx.ax_size;
    bit [1:0]  burst = tx.ax_burst;

    // Check if address is in valid range
    if (!axi4_in_range(addr, len, size, burst)) begin
      `uvm_info("REF", $sformatf("B: addr=0x%0h out of range -> SLVERR", addr), UVM_LOW)
      return `RESP_SLVERR;
    end

    // Check WRAP burst constraints (len must be in {1,3,7,15} and address aligned)
    if (burst == `BURST_WRAP) begin
      if (len != 8'd1 && len != 8'd3 && len != 8'd7 && len != 8'd15) begin
        `uvm_info("REF", $sformatf("B: WRAP len=%0d not in {1,3,7,15} -> SLVERR", len), UVM_LOW)
        return `RESP_SLVERR;
      end
      // Address must be aligned to burst size * data width
      if (addr[2+size] !== 1'b0) begin
        `uvm_info("REF", $sformatf("B: WRAP addr=0x%0h not aligned -> SLVERR", addr), UVM_LOW)
        return `RESP_SLVERR;
      end
    end

    return `RESP_OKAY;
  endfunction

  // -----------------------------------------------------------------------
  // Predict R data for a read transaction (narrow-read simplification:
  // slave does NOT do byte-lane shifting — returns word from memory)
  // -----------------------------------------------------------------------
  function bit [31:0] predict_r_data(axi4_seq_item tx);
    bit [31:0] addr = tx.ax_addr;
    bit [7:0]  len  = tx.ax_len;
    bit [2:0]  size = tx.ax_size;
    bit [1:0]  burst = tx.ax_burst;  
    int        word_idx;

    // Check if address is in valid range
    if (!axi4_in_range(addr, len, size, burst)) begin
      `uvm_info("REF", $sformatf("R: addr=0x%0h out of range -> SLVERR", addr), UVM_LOW)
      return '0;
    end

    // Narrow read simplification: return word from memory at word address
    // No byte-lane shifting — matches DUT behavior exactly
    word_idx = addr[`ADDR_LSB +: `MEM_ADDR_BITS];
    if (word_idx < `C_S_AXI_MEM_DEPTH) begin
      return mem[word_idx];
    end else begin
      return '0;
    end
  endfunction

  // -----------------------------------------------------------------------
  // Predict R response for a read transaction
  // -----------------------------------------------------------------------
  function bit [1:0] predict_r_resp(axi4_seq_item tx);
    bit [31:0] addr = tx.ax_addr;
    bit [7:0]  len  = tx.ax_len;
    bit [2:0]  size = tx.ax_size;
    bit [1:0]  burst = tx.ax_burst;
	
    if (!axi4_in_range(addr, len, size, burst)) begin
      return `RESP_SLVERR;
    end
    return `RESP_OKAY;
  endfunction

  // -----------------------------------------------------------------------
  // Process a write transaction: store data in memory
  // -----------------------------------------------------------------------
  function void process_write(axi4_seq_item tx);
    bit [31:0] addr = tx.ax_addr;
    bit [7:0]  len  = tx.ax_len;
    bit [2:0]  size = tx.ax_size;
    bit [1:0]  burst = tx.ax_burst;
    int        num_beats;
    int        word_idx;
    int        i;
    bit [31:0] beat_addr; 

    // Check if address is in valid range
    if (!axi4_in_range(addr, len, size, burst)) begin
      `uvm_info("REF", $sformatf("W: addr=0x%0h out of range -> SLVERR, not storing", addr), UVM_LOW)
      slverr_sticky = 1'b1;
      return;
    end

    // Reset SLVERR stickiness on successful write
    slverr_sticky = 1'b0;

    // Store data in memory (with byte strobe)
    num_beats = len + 1;
    for (i = 0; i < num_beats; i++) begin
      beat_addr = addr + (i << size);
      word_idx = beat_addr [`ADDR_LSB +: `MEM_ADDR_BITS];
      if (word_idx < `C_S_AXI_MEM_DEPTH) begin
        // Apply write strobe
        mem[word_idx] = apply_wstrb(tx.w_data, tx.w_strb, size);
      end
    end

    `uvm_info("REF", $sformatf("W: stored %0d beats at addr=0x%0h", num_beats, addr), UVM_LOW)
  endfunction

  // -----------------------------------------------------------------------
  // Process a read transaction: return data from memory
  // -----------------------------------------------------------------------
  function void process_read(axi4_seq_item tx);
    bit [31:0] addr = tx.ax_addr;
    bit [7:0]  len  = tx.ax_len;
    bit [2:0]  size = tx.ax_size;
    bit [1:0]  burst = tx.ax_burst;

    // Check if address is in valid range
    if (!axi4_in_range(addr, len, size, burst)) begin
      `uvm_info("REF", $sformatf("R: addr=0x%0h out of range -> SLVERR", addr), UVM_LOW)
      slverr_sticky = 1'b1;
      return;
    end

    // Reset SLVERR stickiness on successful read
    slverr_sticky = 1'b0;

    `uvm_info("REF", $sformatf("R: read from addr=0x%0h", addr), UVM_LOW)
  endfunction

  // -----------------------------------------------------------------------
  // Check if address range is valid for a burst
  // -----------------------------------------------------------------------
  function bit axi4_in_range(bit [31:0] addr, bit [7:0] len, bit [2:0] size, bit [1:0] burst);
    int num_beats = len + 1;
    int transfer_size = (1 << size);
    bit [31:0] last_addr = addr + (num_beats * transfer_size) - 1;

    // Check if last address wraps within legal bounds
    // For simplicity, check if address + burst size stays within memory
    if (last_addr >= (`C_S_AXI_MEM_DEPTH << 2)) begin
      return 1'b0;
    end

    // Check WRAP burst alignment
    if (burst == `BURST_WRAP) begin
      if (len != 8'd1 && len != 8'd3 && len != 8'd7 && len != 8'd15) begin
        return 1'b0;
      end
    end

    return 1'b1;
  endfunction

  // -----------------------------------------------------------------------
  // Apply write strobe to data
  // -----------------------------------------------------------------------
  function bit [31:0] apply_wstrb(bit [31:0] data, bit [`C_S_AXI_STRB_WIDTH-1:0] wstrb, bit [2:0] size);
    bit [31:0] result = '0;
    int num_bytes = (1 << size);
    for (int i = 0; i < num_bytes; i++) begin
      if (wstrb[i]) begin
        result[i*8 +: 8] = data[i*8 +: 8];
      end
    end
    return result;
  endfunction

  // -----------------------------------------------------------------------
  // Get SLVERR stickiness status
  // -----------------------------------------------------------------------
  function bit get_slverr_sticky();
    return slverr_sticky;
  endfunction

endclass

`endif // AXI4_REF_MODEL_SV

// class axi4_scoreboard

// axi4_scoreboard.sv
// File        : axi4_scoreboard.sv
// Description : UVM scoreboard for the AXI4 slave testbench.
//               Receives transactions from driver and monitor,
//               uses axi4_ref_model for expected behavior,
//               compares predicted vs actual responses,
//               tracks SLVERR stickiness.
// Author      : Verification Engineer
// Date        : 2026-09-17
// Revision    : 1.0

`ifndef AXI4_SCOREBOARD_SV
`define AXI4_SCOREBOARD_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"
`include "axi4_ref_model.sv"

class axi4_scoreboard extends uvm_component;

  // -----------------------------------------------------------------------
  // Reference model instance
  // -----------------------------------------------------------------------
  axi4_ref_model ref_model;

  // -----------------------------------------------------------------------
  // Analysis imports: receive transactions from driver and monitor
  // -----------------------------------------------------------------------
  uvm_analysis_imp #(axi4_seq_item, axi4_scoreboard) analysis_export;

  // -----------------------------------------------------------------------
  // Transaction queues for matching
  // -----------------------------------------------------------------------
  axi4_seq_item write_queue[$];
  axi4_seq_item read_queue[$];

  // -----------------------------------------------------------------------
  // Scoreboard statistics
  // -----------------------------------------------------------------------
  int unsigned match_count = 0;
  int unsigned mismatch_count = 0;
  int unsigned error_count = 0;

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_component_utils(axi4_scoreboard)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_scoreboard", uvm_component parent);
    super.new(name, parent);
    analysis_export = new("analysis_export", this);
    `uvm_info("SCB", "axi4_scoreboard constructed", UVM_MEDIUM)
  endfunction

  // -----------------------------------------------------------------------
  // Build phase: create reference model
  // -----------------------------------------------------------------------
  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    ref_model = axi4_ref_model::type_id::create("ref_model", this);
    `uvm_info("SCB", "Reference model created", UVM_LOW)
  endfunction

  // -----------------------------------------------------------------------
  // Write callback: receive transactions from driver/monitor
  // -----------------------------------------------------------------------
  virtual function void write(axi4_seq_item tx);
    if (tx == null) begin
      `uvm_warning("SCB", "Received null transaction")
      return;
    end

    if (tx.is_write) begin
      process_write_tx(tx);
    end else begin
      process_read_tx(tx);
    end
  endfunction

  // -----------------------------------------------------------------------
  // Process a write transaction from driver
  //   - Predict B response using ref_model
  //   - Compare predicted vs actual B response
  //   - Store in write_queue for later matching
  // -----------------------------------------------------------------------
  virtual function void process_write_tx(axi4_seq_item tx);
    bit [1:0] predicted_b_resp = ref_model.predict_b_resp(tx);

    // Store in write queue
    write_queue.push_back(tx);

    // Compare B response
    if (predicted_b_resp != tx.b_resp) begin
      `uvm_error("SCB_W", $sformatf(
        "WRITE B response mismatch: addr=0x%0h id=0x%0h predicted=%0d actual=%0d",
        tx.ax_addr, tx.ax_id, predicted_b_resp, tx.b_resp))
      mismatch_count++;
    end else begin
      `uvm_info("SCB_W", $sformatf(
        "WRITE B response match: addr=0x%0h id=0x%0h resp=%0d",
        tx.ax_addr, tx.ax_id, tx.b_resp), UVM_LOW)
      match_count++;
    end

    // Process write in ref_model (store data in memory)
    ref_model.process_write(tx);
  endfunction

  // -----------------------------------------------------------------------
  // Process a read transaction from monitor
  //   - Predict R data using ref_model
  //   - Compare predicted vs actual R data
  //   - Store in read_queue for later matching
  // -----------------------------------------------------------------------
  virtual function void process_read_tx(axi4_seq_item tx);
    bit [31:0] predicted_r_data = ref_model.predict_r_data(tx);
    bit [1:0]  predicted_r_resp = ref_model.predict_r_resp(tx);

    // Store in read queue
    read_queue.push_back(tx);

    // Compare R data
    if (predicted_r_data !== tx.r_data) begin
      `uvm_error("SCB_R", $sformatf(
        "READ R data mismatch: addr=0x%0h id=0x%0h predicted=0x%0h actual=0x%0h",
        tx.ax_addr, tx.ax_id, predicted_r_data, tx.r_data))
      mismatch_count++;
    end else begin
      `uvm_info("SCB_R", $sformatf(
        "READ R data match: addr=0x%0h id=0x%0h data=0x%0h",
        tx.ax_addr, tx.ax_id, tx.r_data), UVM_LOW)
      match_count++;
    end

    // Compare R response
    if (predicted_r_resp != tx.r_resp) begin
      `uvm_error("SCB_R", $sformatf(
        "READ R response mismatch: addr=0x%0h id=0x%0h predicted=%0d actual=%0d",
        tx.ax_addr, tx.ax_id, predicted_r_resp, tx.r_resp))
      mismatch_count++;
    end

    // Process read in ref_model
    ref_model.process_read(tx);
  endfunction

  // -----------------------------------------------------------------------
  // Check SLVERR stickiness
  // -----------------------------------------------------------------------
  virtual function void check_slverr_sticky(axi4_seq_item tx);
    bit sticky = ref_model.get_slverr_sticky();
    if (sticky && tx.b_resp != `RESP_SLVERR) begin
      `uvm_error("SCB_STICKY", $sformatf(
        "SLVERR stickiness violation: addr=0x%0h expected SLVERR got %0d",
        tx.ax_addr, tx.b_resp))
      mismatch_count++;
    end
  endfunction

  // -----------------------------------------------------------------------
  // Report phase: print scoreboard statistics
  // -----------------------------------------------------------------------
function void report_phase(uvm_phase phase);
    super.report_phase(phase);   
    `uvm_info("SCB", $sformatf({
      "\n=== Scoreboard Report ===\n",
      "  Matches:     %0d\n",
      "  Mismatches:  %0d\n",
      "  Errors:      %0d\n",
      "  Write queue: %0d entries\n",
      "  Read queue:  %0d entries"},
      match_count, mismatch_count, error_count,
      write_queue.size(), read_queue.size()), UVM_LOW)
  endfunction : report_phase

endclass

`endif // AXI4_SCOREBOARD_SV

// class axi4_virtual_sequencer

// axi4_virtual_sequencer.sv
// File        : axi4_virtual_sequencer.sv
// Description : Virtual sequencer for the AXI4 slave testbench.
