  // -----------------------------------------------------------------------
  // References to agent sequencers
  // -----------------------------------------------------------------------
  axi4_sequencer seqr;

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_component_utils(axi4_virtual_sequencer)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_virtual_sequencer", uvm_component parent);
    super.new(name, parent);
