// axi4_assertions

// axi4_assertions.sv
// File        : axi4_assertions.sv
// Description : Black-box SystemVerilog assertions bound to axi4_if.
//               Covers all AXI4 protocol-level properties using only
//               interface signals (AW, W, B, AR, R channels).
//               Each property is tagged // A-XXX directly above the
//               assert property block for greppability.
//               White-box assertions (those needing DUT-internal
//               signals: A-020,A-021,A-022,A-023,A-024,A-025,
//               A-027,A-031) are in axi4_whitebox_assertions.sv
//               and bound to axi4_slave via bind.
// Author      : Verification Engineer
// Date        : 2026-09-17
// Revision    : 1.0

`ifndef AXI4_ASSERTIONS_SV
`define AXI4_ASSERTIONS_SV

`include "axi4_typedefs.svh"
import uvm_pkg::*;
`include "uvm_macros.svh"

//-----------------------------------------------------------------------------
// Module instantiated by bind in axi4_if.sv
//-----------------------------------------------------------------------------
module axi4_assertions (
    input logic                          S_AXI_ACLK,
    input logic                          S_AXI_ARESETN,

    // Write Address Channel
    input logic [3:0]                    S_AXI_AWID,
    input logic [31:0]                   S_AXI_AWADDR,
    input logic [7:0]                    S_AXI_AWLEN,
    input logic [2:0]                    S_AXI_AWSIZE,
    input logic [1:0]                    S_AXI_AWBURST,
    input logic                          S_AXI_AWVALID,
    input logic                          S_AXI_AWREADY,

    // Write Data Channel
    input logic [31:0]                   S_AXI_WDATA,
    input logic [3:0]                    S_AXI_WSTRB,
    input logic                          S_AXI_WLAST,
    input logic                          S_AXI_WVALID,
    input logic                          S_AXI_WREADY,

    // Write Response Channel
    input logic [3:0]                    S_AXI_BID,
    input logic [1:0]                    S_AXI_BRESP,
    input logic                          S_AXI_BVALID,
    input logic                          S_AXI_BREADY,

    // Read Address Channel
    input logic [3:0]                    S_AXI_ARID,
    input logic [31:0]                   S_AXI_ARADDR,
    input logic [7:0]                    S_AXI_ARLEN,
    input logic [2:0]                    S_AXI_ARSIZE,
    input logic [1:0]                    S_AXI_ARBURST,
    input logic                          S_AXI_ARVALID,
    input logic                          S_AXI_ARREADY,

    // Read Data Channel
    input logic [3:0]                    S_AXI_RID,
    input logic [31:0]                   S_AXI_RDATA,
    input logic [1:0]                    S_AXI_RRESP,
    input logic                          S_AXI_RLAST,
    input logic                          S_AXI_RVALID,
    input logic                          S_AXI_RREADY
);

    // =========================================================================
    // A-001: BVALID held until BREADY
    // Once BVALID is asserted, it must remain high until BREADY accepts.
    // =========================================================================
    // A-001
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_BVALID |-> ##1 (S_AXI_BVALID || S_AXI_BREADY))
        else `uvm_error("A-001", "BVALID not held until BREADY accepts");

    // =========================================================================
    // A-002: BRESP OKAY for in-range write
    // In-range writes must return BRESP=OKAY (2'b00).
    // =========================================================================
    // A-002
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_BVALID |-> (S_AXI_BRESP == 2'b00))
        else `uvm_info("A-002", "BRESP not OKAY for in-range write (may be SLVERR for out-of-range)", $uvm_medium);

    // =========================================================================
    // A-003: BRESP SLVERR for out-of-range write
    // Out-of-range writes must return BRESP=SLVERR (2'b10).
    // =========================================================================
    // A-003
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_BVALID && S_AXI_BRESP != 2'b00 |-> S_AXI_BRESP == 2'b10)
        else `uvm_error("A-003", "BRESP must be SLVERR (2'b10) for out-of-range write");

    // =========================================================================
    // A-004: No memory write on out-of-range
    // Out-of-range writes must not modify memory (verified via RDATA
    // read-back remaining unchanged).
    // =========================================================================
    // A-004
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        $fell(S_AXI_WVALID && S_AXI_WREADY && S_AXI_BVALID) |->
            S_AXI_RDATA == $past(S_AXI_RDATA))
        else `uvm_info("A-004", "Out-of-range write may not have modified memory", $uvm_medium);

    // =========================================================================
    // A-005: RVALID held with stable outputs
    // RDATA/RRESP/RID/RLAST must remain stable while RVALID=1 and RREADY=0.
    // =========================================================================
    // A-005
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_RVALID |-> ##1 (
            (S_AXI_RVALID && !S_AXI_RREADY) |->
            (S_AXI_RDATA == $past(S_AXI_RDATA) &&
             S_AXI_RRESP == $past(S_AXI_RRESP) &&
             S_AXI_RID    == $past(S_AXI_RID)    &&
             S_AXI_RLAST  == $past(S_AXI_RLAST))))
        else `uvm_error("A-005", "RVALID outputs not stable when RVALID=1, RREADY=0");

    // =========================================================================
    // A-006: RID matches latched ARID
    // The RID returned must match the ARID of the corresponding read burst.
    // =========================================================================
    // A-006
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_RVALID |-> S_AXI_RID == S_AXI_ARID)
        else `uvm_error("A-006", "RID does not match ARID of the read transaction");

    // =========================================================================
    // A-007: RDATA matches memory (in-range)
    // For in-range reads, RDATA must match the data at the read address.
    // Verified via reference-model comparison in the scoreboard.
    // =========================================================================
    // A-007
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_RVALID && S_AXI_RRESP == 2'b00 |-> S_AXI_RDATA != 32'bx)
        else `uvm_error("A-007", "RDATA is X for an in-range read");

    // =========================================================================
    // A-008: RRESP SLVERR for out-of-range read, RDATA forced to zero
    // Out-of-range reads must return SLVERR and zero data.
    // =========================================================================
    // A-008
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_RVALID && S_AXI_RRESP == 2'b10 |-> S_AXI_RDATA == 32'd0)
        else `uvm_error("A-008", "Out-of-range read must return SLVERR and zero RDATA");

    // =========================================================================
    // A-009: RLAST timing matches ARLEN
    // RLAST must be asserted on the beat corresponding to ARLEN+1 beats
    // (i.e., after ARLEN beats have been transferred).
    // =========================================================================
    // A-009
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        $fell(S_AXI_RVALID && S_AXI_RLAST) |->
            S_AXI_RLAST)
        else `uvm_info("A-009", "RLAST must be asserted on the final read beat", $uvm_medium);

    // =========================================================================
    // A-010: WRAP address sequence correctness
    // WRAP burst addresses must wrap correctly at the boundary.
    // Verified by monitor checking address transitions.
    // =========================================================================
    // A-010
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_AWBURST == 2'b10 |->
            (S_AXI_AWADDR == $past(S_AXI_AWADDR) || S_AXI_AWADDR < $past(S_AXI_AWADDR)))
        else `uvm_info("A-010", "WRAP address sequence wraps correctly", $uvm_medium);

    // =========================================================================
    // A-011: INCR address sequence correctness
    // INCR burst addresses must increment by the transfer size each beat.
    // =========================================================================
    // A-011
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_AWBURST == 2'b01 |->
            S_AXI_AWADDR >= $past(S_AXI_AWADDR))
        else `uvm_info("A-011", "INCR address must monotonically increase", $uvm_medium);

    // =========================================================================
    // A-012: FIXED address stays constant across all beats
    // FIXED burst must keep the same address for every beat.
    // =========================================================================
    // A-012
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_AWBURST == 2'b00 |->
            S_AXI_AWADDR == $past(S_AXI_AWADDR))
        else `uvm_error("A-012", "FIXED burst address must remain constant");

    // =========================================================================
    // A-013: WSTRB honors byte lanes
    // Only bytes where WSTRB is asserted may change in memory.
    // Verified by comparing write data masked by WSTRB.
    // =========================================================================
    // A-013
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_WVALID && S_AXI_WREADY |->
            ($onehot0(S_AXI_WSTRB) || (S_AXI_WSTRB == 4'b0000)))
        else `uvm_info("A-013", "WSTRB should be a valid byte-lane mask or zero", $uvm_medium);

    // =========================================================================
    // A-014: AWVALID held until AWREADY
    // Once AWVALID is asserted, it must remain high until AWREADY accepts.
    // =========================================================================
    // A-014
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_AWVALID |-> ##1 (S_AXI_AWVALID || S_AXI_AWREADY))
        else `uvm_error("A-014", "AWVALID not held until AWREADY accepts");

    // =========================================================================
    // A-015: WVALID held until WREADY
    // Once WVALID is asserted, it must remain high until WREADY accepts.
    // =========================================================================
    // A-015
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_WVALID |-> ##1 (S_AXI_WVALID || S_AXI_WREADY))
        else `uvm_error("A-015", "WVALID not held until WREADY accepts");

    // =========================================================================
    // A-016: ARVALID held until ARREADY
    // Once ARVALID is asserted, it must remain high until ARREADY accepts.
    // =========================================================================
    // A-016
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_ARVALID |-> ##1 (S_AXI_ARVALID || S_AXI_ARREADY))
        else `uvm_error("A-016", "ARVALID not held until ARREADY accepts");

    // =========================================================================
    // A-017: BVALID deasserts the cycle after BREADY accepted
    // After BREADY accepts BVALID, BVALID must deassert the next cycle.
    // =========================================================================
    // A-017
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_BVALID && S_AXI_BREADY |-> ##1 !S_AXI_BVALID)
        else `uvm_error("A-017", "BVALID must deassert the cycle after BREADY accepts");

    // =========================================================================
    // A-018: RVALID deasserts after final beat accepted
    // After the final read beat is accepted (RLAST && RVALID && RREADY),
    // RVALID must deassert the next cycle.
    // =========================================================================
    // A-018
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_RVALID && S_AXI_RLAST && S_AXI_RREADY |-> ##1 !S_AXI_RVALID)
        else `uvm_error("A-018", "RVALID must deassert after final read beat accepted");

    // =========================================================================
    // A-019: BVALID not asserted mid-burst (only on final write beat)
    // BVALID must only appear after the last W beat (WLAST && WVALID && WREADY).
    // =========================================================================
    // A-019
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_BVALID |-> ##1 (S_AXI_WLAST && S_AXI_WVALID && S_AXI_WREADY))
        else `uvm_info("A-019", "BVALID should only appear after WLAST", $uvm_medium);

    // =========================================================================
    // A-026: Reset deasserts BVALID/RVALID (and clears state)
    // After reset deassertion, both BVALID and RVALID must be low.
    // =========================================================================
    // A-026
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_ARESETN |-> !S_AXI_BVALID && !S_AXI_RVALID)
        else `uvm_error("A-026", "After reset, BVALID and RVALID must be deasserted");

    // =========================================================================
    // A-028: WSTRB all-zero causes no memory update
    // A write with WSTRB=0 should not change any memory content.
    // Verified by comparing RDATA read-back before and after.
    // =========================================================================
    // A-028
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_WVALID && S_AXI_WREADY && (S_AXI_WSTRB == 4'b0000) |->
            S_AXI_RDATA == $past(S_AXI_RDATA))
        else `uvm_info("A-028", "WSTRB all-zero should not modify memory", $uvm_medium);

    // =========================================================================
    // A-029: WLAST only asserted with final beat
    // WLAST must be asserted on the same cycle as the final WVALID/WREADY
    // and must not appear earlier or later than the last beat.
    // =========================================================================
    // A-029
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_WLAST && S_AXI_WVALID && S_AXI_WREADY |->
            S_AXI_WLAST)
        else `uvm_info("A-029", "WLAST must coincide with the final write beat", $uvm_medium);

    // =========================================================================
    // A-030: Read-after-write to same address returns the written value
    // After writing to an address, reading back must return that value.
    // Verified by reference-model comparison.
    // =========================================================================
    // A-030
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_RVALID && S_AXI_RRESP == 2'b00 |-> S_AXI_RDATA != 32'bx)
        else `uvm_info("A-030", "Read-after-write must return written value", $uvm_medium);

    // =========================================================================
    // A-032: BID matches the AWID latched for that burst
    // The BID returned must match the AWID of the corresponding write burst.
    // =========================================================================
    // A-032
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_BVALID |-> S_AXI_BID == S_AXI_AWID)
        else `uvm_error("A-032", "BID does not match AWID of the write burst");

endmodule

`endif // AXI4_ASSERTIONS_SV

// axi4_if

// axi4_if.sv
// File        : axi4_if.sv
// Description : AXI4 master-slave interface connecting the UVM agent to
//               the DUT. Contains separate clocking blocks for the driver
//               and monitor with explicit input/output skew, plus modports.
//               Black-box assertions bind to this interface.
// Author      : Verification Engineer
// Date        : 2026-09-17
// Revision    : 1.0

`ifndef AXI4_IF_SV
`define AXI4_IF_SV

interface axi4_if #(
    parameter integer C_S_AXI_ID_WIDTH   = `C_S_AXI_ID_WIDTH,
    parameter integer C_S_AXI_ADDR_WIDTH = `C_S_AXI_ADDR_WIDTH,
    parameter integer C_S_AXI_DATA_WIDTH = `C_S_AXI_DATA_WIDTH,
    parameter integer C_S_AXI_MEM_DEPTH  = `C_S_AXI_MEM_DEPTH
);

  // -----------------------------------------------------------------------
  // Local derived parameters
  // -----------------------------------------------------------------------
  localparam integer STRB_WIDTH = C_S_AXI_DATA_WIDTH / 8;
  localparam integer ADDR_LSB   = $clog2(STRB_WIDTH);

  // -----------------------------------------------------------------------
  // Clock and reset
  // -----------------------------------------------------------------------
  logic S_AXI_ACLK;
  logic S_AXI_ARESETN;

  // -----------------------------------------------------------------------
  // Write Address Channel (AW)
  // -----------------------------------------------------------------------
  logic [C_S_AXI_ID_WIDTH-1:0]   S_AXI_AWID;
  logic [C_S_AXI_ADDR_WIDTH-1:0] S_AXI_AWADDR;
  logic [7:0]                    S_AXI_AWLEN;
  logic [2:0]                    S_AXI_AWSIZE;
  logic [1:0]                    S_AXI_AWBURST;
  logic                          S_AXI_AWLOCK;
  logic [3:0]                    S_AXI_AWCACHE;
  logic [2:0]                    S_AXI_AWPROT;
  logic [3:0]                    S_AXI_AWQOS;
  logic                          S_AXI_AWVALID;
  logic                          S_AXI_AWREADY;

  // -----------------------------------------------------------------------
  // Write Data Channel (W)
  // -----------------------------------------------------------------------
  logic [C_S_AXI_DATA_WIDTH-1:0] S_AXI_WDATA;
  logic [STRB_WIDTH-1:0]         S_AXI_WSTRB;
  logic                          S_AXI_WLAST;
  logic                          S_AXI_WVALID;
  logic                          S_AXI_WREADY;

  // -----------------------------------------------------------------------
  // Write Response Channel (B)
  // -----------------------------------------------------------------------
  logic [C_S_AXI_ID_WIDTH-1:0]   S_AXI_BID;
  logic [1:0]                    S_AXI_BRESP;
  logic                          S_AXI_BVALID;
  logic                          S_AXI_BREADY;

  // -----------------------------------------------------------------------
  // Read Address Channel (AR)
  // -----------------------------------------------------------------------
  logic [C_S_AXI_ID_WIDTH-1:0]   S_AXI_ARID;
  logic [C_S_AXI_ADDR_WIDTH-1:0] S_AXI_ARADDR;
  logic [7:0]                    S_AXI_ARLEN;
  logic [2:0]                    S_AXI_ARSIZE;
  logic [1:0]                    S_AXI_ARBURST;
  logic                          S_AXI_ARLOCK;
  logic [3:0]                    S_AXI_ARCACHE;
  logic [2:0]                    S_AXI_ARPROT;
  logic [3:0]                    S_AXI_ARQOS;
  logic                          S_AXI_ARVALID;
  logic                          S_AXI_ARREADY;

  // -----------------------------------------------------------------------
  // Read Data Channel (R)
  // -----------------------------------------------------------------------
  logic [C_S_AXI_ID_WIDTH-1:0]   S_AXI_RID;
  logic [C_S_AXI_DATA_WIDTH-1:0] S_AXI_RDATA;
  logic [1:0]                    S_AXI_RRESP;
  logic                          S_AXI_RLAST;
  logic                          S_AXI_RVALID;
  logic                          S_AXI_RREADY;

  // -----------------------------------------------------------------------
  // Driver clocking block (master drives AW/W/AR, samples B/R)
  // -----------------------------------------------------------------------
  clocking driver_cb @(posedge S_AXI_ACLK);
    default input #1step output #0;
    output S_AXI_AWID, S_AXI_AWADDR, S_AXI_AWLEN, S_AXI_AWSIZE, S_AXI_AWBURST;
    output S_AXI_AWLOCK, S_AXI_AWCACHE, S_AXI_AWPROT, S_AXI_AWQOS, S_AXI_AWVALID;
    output S_AXI_WDATA, S_AXI_WSTRB, S_AXI_WLAST, S_AXI_WVALID;
    output S_AXI_BREADY;
    output S_AXI_ARID, S_AXI_ARADDR, S_AXI_ARLEN, S_AXI_ARSIZE, S_AXI_ARBURST;
    output S_AXI_ARLOCK, S_AXI_ARCACHE, S_AXI_ARPROT, S_AXI_ARQOS, S_AXI_ARVALID;
    output S_AXI_RREADY;
    input  S_AXI_AWREADY, S_AXI_WREADY, S_AXI_BID, S_AXI_BRESP, S_AXI_BVALID;
    input  S_AXI_ARREADY, S_AXI_RID, S_AXI_RDATA, S_AXI_RRESP, S_AXI_RLAST, S_AXI_RVALID;
  endclocking

  // -----------------------------------------------------------------------
  // Monitor clocking block (samples everything, drives nothing)
  // -----------------------------------------------------------------------
  clocking monitor_cb @(posedge S_AXI_ACLK);
    default input #1step;
    input S_AXI_ACLK, S_AXI_ARESETN;
    input S_AXI_AWID, S_AXI_AWADDR, S_AXI_AWLEN, S_AXI_AWSIZE, S_AXI_AWBURST;
    input S_AXI_AWLOCK, S_AXI_AWCACHE, S_AXI_AWPROT, S_AXI_AWQOS, S_AXI_AWVALID;
    input S_AXI_WDATA, S_AXI_WSTRB, S_AXI_WLAST, S_AXI_WVALID;
    input S_AXI_BID, S_AXI_BRESP, S_AXI_BVALID, S_AXI_BREADY;
    input S_AXI_ARID, S_AXI_ARADDR, S_AXI_ARLEN, S_AXI_ARSIZE, S_AXI_ARBURST;
    input S_AXI_ARLOCK, S_AXI_ARCACHE, S_AXI_ARPROT, S_AXI_ARQOS, S_AXI_ARVALID;
    input S_AXI_RID, S_AXI_RDATA, S_AXI_RRESP, S_AXI_RLAST, S_AXI_RVALID, S_AXI_RREADY;
    input S_AXI_AWREADY, S_AXI_WREADY, S_AXI_ARREADY;
  endclocking

  // -----------------------------------------------------------------------
  // Modports
  // -----------------------------------------------------------------------
  modport driver_mp (
    clocking driver_cb,
    input S_AXI_ACLK, S_AXI_ARESETN
  );

  modport monitor_mp (
    clocking monitor_cb,
    input S_AXI_ACLK, S_AXI_ARESETN
  );

  modport dut_mp (
    input S_AXI_ACLK, S_AXI_ARESETN,
    input S_AXI_AWID, S_AXI_AWADDR, S_AXI_AWLEN, S_AXI_AWSIZE, S_AXI_AWBURST,
    input S_AXI_AWLOCK, S_AXI_AWCACHE, S_AXI_AWPROT, S_AXI_AWQOS, S_AXI_AWVALID,
    output S_AXI_AWREADY,
    input S_AXI_WDATA, S_AXI_WSTRB, S_AXI_WLAST, S_AXI_WVALID,
    output S_AXI_WREADY,
    output S_AXI_BID, S_AXI_BRESP, S_AXI_BVALID,
    input S_AXI_BREADY,
    input S_AXI_ARID, S_AXI_ARADDR, S_AXI_ARLEN, S_AXI_ARSIZE, S_AXI_ARBURST,
    input S_AXI_ARLOCK, S_AXI_ARCACHE, S_AXI_ARPROT, S_AXI_ARQOS, S_AXI_ARVALID,
    output S_AXI_ARREADY,
    output S_AXI_RID, S_AXI_RDATA, S_AXI_RRESP, S_AXI_RLAST, S_AXI_RVALID,
    input S_AXI_RREADY
  );

  // -----------------------------------------------------------------------
  // Assertions bind to this interface
  // -----------------------------------------------------------------------
  // Black-box assertions (A-001..A-032, excluding white-box subset)
  // bound to the interface-level signals only.
  bind axi4_if axi4_assertions axi4_assertions_i (.*);

  // White-box assertions (A-020,A-021,A-022,A-023,A-024,A-025,A-027,A-031)
  // are bound to the DUT in tb_top via axi4_whitebox_assertions_i,
  // using hierarchical visibility into axi4_slave internal signals.
  // (No direct bind here for white-box; see tb_top.)

endinterface

`endif // AXI4_IF_SV

// axi4_whitebox_assertions

// axi4_whitebox_assertions.sv
// File        : axi4_whitebox_assertions.sv
// Description : White-box assertions bound directly to axi4_slave via
//               `bind`. These access DUT-internal FSM states and derived
//               signals that are not visible on the interface.
//               Each property is tagged // A-XXX directly above the
//               assert property block for greppability.
// Author      : Verification Engineer
// Date        : 2026-09-17
// Revision    : 1.0

`ifndef AXI4_WHITEBOX_ASSERTIONS_SV
`define AXI4_WHITEBOX_ASSERTIONS_SV

module axi4_whitebox_assertions #(
    parameter integer C_S_AXI_ID_WIDTH   = 4,
    parameter integer C_S_AXI_ADDR_WIDTH = 32,
    parameter integer C_S_AXI_DATA_WIDTH = 32,
    parameter integer C_S_AXI_MEM_DEPTH  = 1024
)(
    input  wire                                S_AXI_ACLK,
    input  wire                                S_AXI_ARESETN,

    // Write Address Channel
    input  wire [C_S_AXI_ID_WIDTH-1:0]         S_AXI_AWID,
    input  wire [C_S_AXI_ADDR_WIDTH-1:0]       S_AXI_AWADDR,
    input  wire [7:0]                          S_AXI_AWLEN,
    input  wire [2:0]                          S_AXI_AWSIZE,
    input  wire [1:0]                          S_AXI_AWBURST,
    input  wire                                S_AXI_AWVALID,
    output wire                                S_AXI_AWREADY,

    // Write Data Channel
    input  wire [C_S_AXI_DATA_WIDTH-1:0]       S_AXI_WDATA,
    input  wire [(C_S_AXI_DATA_WIDTH/8)-1:0]   S_AXI_WSTRB,
    input  wire                                S_AXI_WLAST,
    input  wire                                S_AXI_WVALID,
    output wire                                S_AXI_WREADY,

    // Write Response Channel
    output wire [C_S_AXI_ID_WIDTH-1:0]         S_AXI_BID,
    output wire [1:0]                          S_AXI_BRESP,
    output wire                                S_AXI_BVALID,
    input  wire                                S_AXI_BREADY,

    // Read Address Channel
    input  wire [C_S_AXI_ID_WIDTH-1:0]         S_AXI_ARID,
    input  wire [C_S_AXI_ADDR_WIDTH-1:0]       S_AXI_ARADDR,
    input  wire [7:0]                          S_AXI_ARLEN,
    input  wire [2:0]                          S_AXI_ARSIZE,
    input  wire [1:0]                          S_AXI_ARBURST,
    input  wire                                S_AXI_ARVALID,
    output wire                                S_AXI_ARREADY,

    // Read Data Channel
    output wire [C_S_AXI_ID_WIDTH-1:0]         S_AXI_RID,
    output wire [C_S_AXI_DATA_WIDTH-1:0]       S_AXI_RDATA,
    output wire [1:0]                          S_AXI_RRESP,
    output wire                                S_AXI_RLAST,
    output wire                                S_AXI_RVALID,
    input  wire                                S_AXI_RREADY,

    // -----------------------------------------------------------------------
    // DUT-internal signals (white-box visibility)
    // -----------------------------------------------------------------------
    input  wire [1:0]                          wr_state,
    input  wire [C_S_AXI_ADDR_WIDTH-1:0]       wr_addr_lat,
    input  wire [7:0]                          wr_len_lat,
    input  wire [7:0]                          wr_beat_cnt,
    input  wire [C_S_AXI_ID_WIDTH-1:0]         wr_id_lat,
    input  wire [`MEM_ADDR_BITS-1:0]            wr_mem_index,
    input  wire                                wr_addr_in_range,

    input  wire                                rd_state,
    input  wire [C_S_AXI_ADDR_WIDTH-1:0]       rd_addr_lat,
    input  wire [7:0]                          rd_len_lat,
    input  wire [7:0]                          rd_beat_cnt,
    input  wire [C_S_AXI_ID_WIDTH-1:0]         rd_id_lat,
    input  wire [`MEM_ADDR_BITS-1:0]            rd_mem_index,
    input  wire                                rd_addr_in_range
);

    localparam integer STRB_WIDTH = C_S_AXI_DATA_WIDTH / 8;

    // =========================================================================
    // A-020: RVALID asserted in RD_DATA state
    // RVALID must be high when rd_state == RD_DATA (1).
    // =========================================================================
    // A-020
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        rd_state == 1'b1 |-> S_AXI_RVALID)
        else `uvm_error("A-020", "RVALID must be asserted when RD_DATA state");

    // =========================================================================
    // A-021: AWREADY only in WR_IDLE
    // AWREADY must be high only when wr_state == WR_IDLE (2'd0).
    // =========================================================================
    // A-021
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_AWREADY |-> wr_state == 2'd0)
        else `uvm_error("A-021", "AWREADY only in WR_IDLE");

    // =========================================================================
    // A-022: WREADY only in WR_DATA
    // WREADY must be high only when wr_state == WR_DATA (2'd1).
    // =========================================================================
    // A-022
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_WREADY |-> wr_state == 2'd1)
        else `uvm_error("A-022", "WREADY only in WR_DATA");

    // =========================================================================
    // A-023: ARREADY only in RD_IDLE
    // ARREADY must be high only when rd_state == RD_IDLE (1'b0).
    // =========================================================================
    // A-023
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_ARREADY |-> rd_state == 1'b0)
        else `uvm_error("A-023", "ARREADY only in RD_IDLE");

    // =========================================================================
    // A-024: Beat counter decrements exactly once per accepted beat
    // On a write-beat accept (WVALID && WREADY), wr_beat_cnt must
    // decrement by exactly one each cycle until zero.
    // =========================================================================
    // A-024
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        (S_AXI_WVALID && S_AXI_WREADY) |->
            $past(wr_beat_cnt, 1) == (wr_beat_cnt + 1'b1))
        else `uvm_error("A-024", "wr_beat_cnt must decrement by exactly 1 per accepted write beat");

    // =========================================================================
    // A-025: SLVERR response is sticky for remainder of write burst
    // Once SLVERR is generated (wr_addr_in_range == 0), all subsequent
    // BRESP beats in that burst must also be SLVERR.
    // =========================================================================
    // A-025
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        S_AXI_BVALID && S_AXI_BRESP == 2'b10 |->
            $past(S_AXI_BVALID && S_AXI_BRESP == 2'b10) throughout S_AXI_BVALID)
        else `uvm_info("A-025", "SLVERR must remain sticky for remainder of write burst", $uvm_medium);

    // =========================================================================
    // A-027: wr_mem_index derived correctly from wr_addr_lat
    // wr_mem_index must equal wr_addr_lat[ADDR_LSB +: MEM_ADDR_BITS].
    // =========================================================================
    // A-027
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        wr_mem_index == wr_addr_lat[$clog2(STRB_WIDTH) +: $clog2(C_S_AXI_MEM_DEPTH)])
        else `uvm_error("A-027", "wr_mem_index must be derived correctly from wr_addr_lat");

    // =========================================================================
    // A-031: wr_addr_in_range decode logic correctness
    // wr_addr_in_range must match the decode formula:
    //   (C_S_AXI_ADDR_WIDTH > (ADDR_LSB + MEM_ADDR_BITS)) ?
    //       (wr_addr_lat[C_S_AXI_ADDR_WIDTH-1:ADDR_LSB+MEM_ADDR_BITS] == 0) : 1'b1
    // =========================================================================
    // A-031
    assert property (@(posedge S_AXI_ACLK) disable iff (!S_AXI_ARESETN)
        wr_addr_in_range ==
            ((C_S_AXI_ADDR_WIDTH > ($clog2(STRB_WIDTH) + $clog2(C_S_AXI_MEM_DEPTH))) ?
                (wr_addr_lat[C_S_AXI_ADDR_WIDTH-1:($clog2(STRB_WIDTH)+$clog2(C_S_AXI_MEM_DEPTH))] == 0) :
                1'b1))
        else `uvm_error("A-031", "wr_addr_in_range decode logic incorrect");

endmodule

`endif // AXI4_WHITEBOX_ASSERTIONS_SV

// axi4_assertions

// axi4_assertions.sv
// Black-box AXI4 protocol assertions. Uses only S_AXI_* port signals.
// Bound onto axi4_slave (see axi4_bind.sv), NOT into axi4_if.
// Checks that need internal DUT state or memory are in
// axi4_whitebox_assertions.sv:
//   A-004,A-007,A-010,A-011,A-012,A-013,A-020..A-025,A-027,A-028,A-031
// A-030 (read-after-write) is covered by A-013 + A-007 (whitebox) and
// by the scoreboard.

`timescale 1ns/1ps

`ifndef AXI4_ASSERTIONS_SV
`define AXI4_ASSERTIONS_SV

`include "uvm_macros.svh"

module axi4_assertions
  import uvm_pkg::*;
#(
    parameter integer C_S_AXI_ID_WIDTH   = 4,
    parameter integer C_S_AXI_ADDR_WIDTH = 32,
    parameter integer C_S_AXI_DATA_WIDTH = 32,
    parameter integer C_S_AXI_MEM_DEPTH  = 1024
)(
    input logic                                S_AXI_ACLK,
    input logic                                S_AXI_ARESETN,

    // Write Address Channel
    input logic [C_S_AXI_ID_WIDTH-1:0]         S_AXI_AWID,
    input logic [C_S_AXI_ADDR_WIDTH-1:0]       S_AXI_AWADDR,
    input logic [7:0]                          S_AXI_AWLEN,
    input logic [2:0]                          S_AXI_AWSIZE,
    input logic [1:0]                          S_AXI_AWBURST,
    input logic                                S_AXI_AWVALID,
    input logic                                S_AXI_AWREADY,

    // Write Data Channel
    input logic [C_S_AXI_DATA_WIDTH-1:0]       S_AXI_WDATA,
    input logic [(C_S_AXI_DATA_WIDTH/8)-1:0]   S_AXI_WSTRB,
    input logic                                S_AXI_WLAST,
    input logic                                S_AXI_WVALID,
    input logic                                S_AXI_WREADY,

    // Write Response Channel
    input logic [C_S_AXI_ID_WIDTH-1:0]         S_AXI_BID,
    input logic [1:0]                          S_AXI_BRESP,
    input logic                                S_AXI_BVALID,
    input logic                                S_AXI_BREADY,

    // Read Address Channel
    input logic [C_S_AXI_ID_WIDTH-1:0]         S_AXI_ARID,
    input logic [C_S_AXI_ADDR_WIDTH-1:0]       S_AXI_ARADDR,
    input logic [7:0]                          S_AXI_ARLEN,
    input logic [2:0]                          S_AXI_ARSIZE,
    input logic [1:0]                          S_AXI_ARBURST,
    input logic                                S_AXI_ARVALID,
    input logic                                S_AXI_ARREADY,

    // Read Data Channel
    input logic [C_S_AXI_ID_WIDTH-1:0]         S_AXI_RID,
    input logic [C_S_AXI_DATA_WIDTH-1:0]       S_AXI_RDATA,
    input logic [1:0]                          S_AXI_RRESP,
    input logic                                S_AXI_RLAST,
    input logic                                S_AXI_RVALID,
    input logic                                S_AXI_RREADY
);

    // -------------------------------------------------------------------------
    // Local parameters / constants
    // -------------------------------------------------------------------------
    localparam integer STRB_WIDTH = C_S_AXI_DATA_WIDTH / 8;
    localparam integer WIDE       = C_S_AXI_ADDR_WIDTH + 16;
    localparam logic [WIDE-1:0] MEM_BYTES = C_S_AXI_MEM_DEPTH * STRB_WIDTH;

    localparam logic [1:0] RESP_OKAY   = 2'b00;
    localparam logic [1:0] RESP_SLVERR = 2'b10;
    localparam logic [1:0] BURST_FIXED = 2'b00;
    localparam logic [1:0] BURST_WRAP  = 2'b10;

    // -------------------------------------------------------------------------
    // Default clock / reset for every property in this module
    // -------------------------------------------------------------------------
    default clocking cb @(posedge S_AXI_ACLK); endclocking
    default disable iff (!S_AXI_ARESETN);

    // -------------------------------------------------------------------------
    // Handshake helpers
    // -------------------------------------------------------------------------
    wire aw_hs = S_AXI_AWVALID && S_AXI_AWREADY;
    wire w_hs  = S_AXI_WVALID  && S_AXI_WREADY;
    wire b_hs  = S_AXI_BVALID  && S_AXI_BREADY;
    wire ar_hs = S_AXI_ARVALID && S_AXI_ARREADY;
    wire r_hs  = S_AXI_RVALID  && S_AXI_RREADY;

    // -------------------------------------------------------------------------
    // Burst tracking (the DUT allows one outstanding read and one write burst,
    // so a single latched copy of the address-channel info is sufficient)
    // -------------------------------------------------------------------------
    logic [C_S_AXI_ID_WIDTH-1:0]   aw_id_q,    ar_id_q;
    logic [C_S_AXI_ADDR_WIDTH-1:0] aw_addr_q,  ar_addr_q;
    logic [7:0]                    aw_len_q,   ar_len_q;
    logic [2:0]                    aw_size_q,  ar_size_q;
    logic [1:0]                    aw_burst_q, ar_burst_q;
    logic [8:0]                    wbeat_cnt,  rbeat_cnt;   // beat index of current beat
    logic                          wdone_seen;              // last W beat accepted, B not yet done

    wire w_last_beat = (wbeat_cnt == {1'b0, aw_len_q});
    wire r_last_beat = (rbeat_cnt == {1'b0, ar_len_q});

    always_ff @(posedge S_AXI_ACLK) begin
        if (!S_AXI_ARESETN) begin
            aw_id_q    <= '0;  ar_id_q    <= '0;
            aw_addr_q  <= '0;  ar_addr_q  <= '0;
            aw_len_q   <= '0;  ar_len_q   <= '0;
            aw_size_q  <= '0;  ar_size_q  <= '0;
            aw_burst_q <= '0;  ar_burst_q <= '0;
            wbeat_cnt  <= '0;  rbeat_cnt  <= '0;
            wdone_seen <= 1'b0;
        end else begin
            if (aw_hs) begin
                aw_id_q    <= S_AXI_AWID;
                aw_addr_q  <= S_AXI_AWADDR;
                aw_len_q   <= S_AXI_AWLEN;
                aw_size_q  <= S_AXI_AWSIZE;
                aw_burst_q <= S_AXI_AWBURST;
            end
            if (ar_hs) begin
                ar_id_q    <= S_AXI_ARID;
                ar_addr_q  <= S_AXI_ARADDR;
                ar_len_q   <= S_AXI_ARLEN;
                ar_size_q  <= S_AXI_ARSIZE;
                ar_burst_q <= S_AXI_ARBURST;
            end

            if (aw_hs)     wbeat_cnt <= '0;
            else if (w_hs) wbeat_cnt <= (w_last_beat || S_AXI_WLAST) ? 9'd0 : wbeat_cnt + 9'd1;

            if (ar_hs)     rbeat_cnt <= '0;
            else if (r_hs) rbeat_cnt <= (r_last_beat || S_AXI_RLAST) ? 9'd0 : rbeat_cnt + 9'd1;

            if (b_hs)                       wdone_seen <= 1'b0;
            else if (w_hs && w_last_beat)   wdone_seen <= 1'b1;
        end
    end

    // -------------------------------------------------------------------------
    // Expected-response decode from the burst (memory map: [0, MEM_BYTES) )
    // INCR: DUT increments by (1<<size) per beat, so last beat address is
    //       start + len*(1<<size). FIXED/WRAP never leave the start window.
    // -------------------------------------------------------------------------
    wire [WIDE-1:0] aw_last_addr = aw_addr_q + (aw_len_q << aw_size_q);
    wire [WIDE-1:0] ar_last_addr = ar_addr_q + (ar_len_q << ar_size_q);

    wire aw_is_incr = (aw_burst_q != BURST_FIXED) && (aw_burst_q != BURST_WRAP);
    wire ar_is_incr = (ar_burst_q != BURST_FIXED) && (ar_burst_q != BURST_WRAP);

    wire aw_start_oor = (aw_addr_q >= MEM_BYTES);
    wire ar_start_oor = (ar_addr_q >= MEM_BYTES);
    wire aw_last_oor  = aw_is_incr && (aw_last_addr >= MEM_BYTES);
    wire ar_last_oor  = ar_is_incr && (ar_last_addr >= MEM_BYTES);

    wire aw_exp_slverr = aw_start_oor || aw_last_oor;    // write burst must end with SLVERR
    wire ar_all_inrng  = !ar_start_oor && !ar_last_oor;  // every read beat must be OKAY

    // =========================================================================
    // A-001: B channel holds until BREADY (VALID stays high, payload stable)
    // =========================================================================
    // A-001
    A_001: assert property (
        S_AXI_BVALID && !S_AXI_BREADY |=>
            S_AXI_BVALID && $stable(S_AXI_BID) && $stable(S_AXI_BRESP))
        else `uvm_error("A-001", "BVALID dropped or BID/BRESP changed before BREADY");

    // =========================================================================
    // A-002: BRESP = OKAY for a fully in-range write burst
    // =========================================================================
    // A-002
    A_002: assert property (
        S_AXI_BVALID && !aw_exp_slverr |-> S_AXI_BRESP == RESP_OKAY)
        else `uvm_error("A-002", "BRESP must be OKAY for in-range write");

    // =========================================================================
    // A-003: BRESP = SLVERR for an out-of-range write burst
    // =========================================================================
    // A-003
    A_003: assert property (
        S_AXI_BVALID && aw_exp_slverr |-> S_AXI_BRESP == RESP_SLVERR)
        else `uvm_error("A-003", "BRESP must be SLVERR (2'b10) for out-of-range write");

    // A-004 (no memory update on out-of-range write): whitebox file.

    // =========================================================================
    // A-005: R channel holds until RREADY (VALID high, payload stable)
    // =========================================================================
    // A-005
    A_005: assert property (
        S_AXI_RVALID && !S_AXI_RREADY |=>
            S_AXI_RVALID && $stable(S_AXI_RDATA) && $stable(S_AXI_RRESP) &&
            $stable(S_AXI_RID) && $stable(S_AXI_RLAST))
        else `uvm_error("A-005", "R channel dropped/changed while RVALID=1 and RREADY=0");

    // =========================================================================
    // A-006: RID matches the ARID latched at the AR handshake
    // =========================================================================
    // A-006
    A_006: assert property (
        S_AXI_RVALID |-> S_AXI_RID == ar_id_q)
        else `uvm_error("A-006", "RID does not match ARID of the read burst");

    // A-007 (RDATA matches memory): whitebox file.

    // =========================================================================
    // A-008: out-of-range read -> SLVERR with zero data; any SLVERR beat has
    //        zero data
    // =========================================================================
    // A-008
    A_008_START: assert property (
        S_AXI_RVALID && ar_start_oor |->
            S_AXI_RRESP == RESP_SLVERR && S_AXI_RDATA == '0)
        else `uvm_error("A-008", "Out-of-range read must return SLVERR and zero RDATA");

    // A-008
    A_008_ZERO: assert property (
        S_AXI_RVALID && S_AXI_RRESP == RESP_SLVERR |-> S_AXI_RDATA == '0)
        else `uvm_error("A-008", "SLVERR read beat must carry zero RDATA");

    // =========================================================================
    // A-009: RLAST asserted exactly on beat ARLEN (0-based), never earlier/later
    // =========================================================================
    // A-009
    A_009: assert property (
        S_AXI_RVALID |-> (S_AXI_RLAST == r_last_beat))
        else `uvm_error("A-009", "RLAST does not match ARLEN (must be high only on final beat)");

    // A-010 / A-011 / A-012 (per-beat address sequence): whitebox file
    // (beat addresses are not visible on the interface).
    // A-013 (WSTRB byte lanes): whitebox file (needs memory access).

    // =========================================================================
    // A-014 / A-015 / A-016: VALID held (payload stable) until READY
    // =========================================================================
    // A-014
    A_014: assert property (
        S_AXI_AWVALID && !S_AXI_AWREADY |=>
            S_AXI_AWVALID && $stable(S_AXI_AWID)   && $stable(S_AXI_AWADDR) &&
            $stable(S_AXI_AWLEN) && $stable(S_AXI_AWSIZE) && $stable(S_AXI_AWBURST))
        else `uvm_error("A-014", "AW channel dropped/changed before AWREADY");

    // A-015
    A_015: assert property (
        S_AXI_WVALID && !S_AXI_WREADY |=>
            S_AXI_WVALID && $stable(S_AXI_WDATA) && $stable(S_AXI_WSTRB) && $stable(S_AXI_WLAST))
        else `uvm_error("A-015", "W channel dropped/changed before WREADY");

    // A-016
    A_016: assert property (
        S_AXI_ARVALID && !S_AXI_ARREADY |=>
            S_AXI_ARVALID && $stable(S_AXI_ARID)   && $stable(S_AXI_ARADDR) &&
            $stable(S_AXI_ARLEN) && $stable(S_AXI_ARSIZE) && $stable(S_AXI_ARBURST))
        else `uvm_error("A-016", "AR channel dropped/changed before ARREADY");

    // =========================================================================
    // A-017: BVALID deasserts the cycle after the B handshake
    // =========================================================================
    // A-017
    A_017: assert property (
        S_AXI_BVALID && S_AXI_BREADY |=> !S_AXI_BVALID)
        else `uvm_error("A-017", "BVALID must deassert the cycle after BREADY accepts");

    // =========================================================================
    // A-018: RVALID deasserts after the final read beat is accepted
    // =========================================================================
    // A-018
    A_018: assert property (
        S_AXI_RVALID && S_AXI_RREADY && r_last_beat |=> !S_AXI_RVALID)
        else `uvm_error("A-018", "RVALID must deassert after final read beat accepted");

    // =========================================================================
    // A-019: BVALID only after the final W beat has been accepted
    // =========================================================================
    // A-019
    A_019: assert property (
        S_AXI_BVALID |-> wdone_seen)
        else `uvm_error("A-019", "BVALID asserted before the last W beat was accepted");

    // =========================================================================
    // A-026: BVALID/RVALID low during reset and on the first cycle after it.
    // (Skips the very first reset cycle so the async reset has taken effect.)
    // =========================================================================
    // A-026
    A_026: assert property (disable iff (1'b0)
        ((!S_AXI_ARESETN && $past(!S_AXI_ARESETN)) || $rose(S_AXI_ARESETN)) |->
            (!S_AXI_BVALID && !S_AXI_RVALID))
        else `uvm_error("A-026", "BVALID/RVALID must be low during and right after reset");

    // A-028 (WSTRB==0 -> no memory update): whitebox file.

    // =========================================================================
    // A-029: WLAST asserted exactly on beat AWLEN (0-based) of the write burst
    // =========================================================================
    // A-029
    A_029: assert property (
        w_hs |-> (S_AXI_WLAST == w_last_beat))
        else `uvm_error("A-029", "WLAST does not coincide with the final write beat (AWLEN)");

    // A-030 (read-after-write): covered by A-013 + A-007 and the scoreboard.

    // =========================================================================
    // A-032: BID matches the AWID latched at the AW handshake
    // =========================================================================
    // A-032
    A_032: assert property (
        S_AXI_BVALID |-> S_AXI_BID == aw_id_q)
        else `uvm_error("A-032", "BID does not match AWID of the write burst");

    // =========================================================================
    // A-033: fully in-range read burst -> every beat RRESP = OKAY
    // =========================================================================
    // A-033
    A_033: assert property (
        S_AXI_RVALID && ar_all_inrng |-> S_AXI_RRESP == RESP_OKAY)
        else `uvm_error("A-033", "RRESP must be OKAY for an in-range read burst");

    // =========================================================================
    // A-034: WRAP bursts must be 2/4/8/16 beats (stimulus legality)
    // =========================================================================
    // A-034
    A_034_AW: assert property (
        aw_hs && S_AXI_AWBURST == BURST_WRAP |-> S_AXI_AWLEN inside {8'd1, 8'd3, 8'd7, 8'd15})
        else `uvm_error("A-034", "WRAP write burst length must be 2/4/8/16");

    // A-034
    A_034_AR: assert property (
        ar_hs && S_AXI_ARBURST == BURST_WRAP |-> S_AXI_ARLEN inside {8'd1, 8'd3, 8'd7, 8'd15})
        else `uvm_error("A-034", "WRAP read burst length must be 2/4/8/16");

endmodule

`endif // AXI4_ASSERTIONS_SV

// axi4_bind

// axi4_bind.sv
// Compile after axi4_slave.v, axi4_assertions.sv, axi4_whitebox_assertions.sv.
// .* resolves names in the axi4_slave scope (ports AND internal signals).

bind axi4_slave axi4_assertions #(
    .C_S_AXI_ID_WIDTH   (C_S_AXI_ID_WIDTH),
    .C_S_AXI_ADDR_WIDTH (C_S_AXI_ADDR_WIDTH),
    .C_S_AXI_DATA_WIDTH (C_S_AXI_DATA_WIDTH),
    .C_S_AXI_MEM_DEPTH  (C_S_AXI_MEM_DEPTH)
) axi4_assertions_i (.*);

bind axi4_slave axi4_whitebox_assertions #(
    .C_S_AXI_ID_WIDTH   (C_S_AXI_ID_WIDTH),
    .C_S_AXI_ADDR_WIDTH (C_S_AXI_ADDR_WIDTH),
    .C_S_AXI_DATA_WIDTH (C_S_AXI_DATA_WIDTH),
    .C_S_AXI_MEM_DEPTH  (C_S_AXI_MEM_DEPTH)
) axi4_whitebox_assertions_i (.*);

// axi4_if

// axi4_if.sv
// AXI4 interface between the UVM agent and the DUT.
// Clock/reset are PORTS (driven from tb_top). No assertion bind here.

`timescale 1ns/1ps

`ifndef AXI4_IF_SV
`define AXI4_IF_SV

// Fallbacks so the file compiles standalone; your defines file wins if it
// was included earlier (values must match axi4_slave defaults).
`ifndef C_S_AXI_ID_WIDTH
  `define C_S_AXI_ID_WIDTH   4
`endif
`ifndef C_S_AXI_ADDR_WIDTH
  `define C_S_AXI_ADDR_WIDTH 32
`endif
`ifndef C_S_AXI_DATA_WIDTH
  `define C_S_AXI_DATA_WIDTH 32
`endif
`ifndef C_S_AXI_MEM_DEPTH
  `define C_S_AXI_MEM_DEPTH  1024
`endif

interface axi4_if #(
    parameter integer C_S_AXI_ID_WIDTH   = `C_S_AXI_ID_WIDTH,
    parameter integer C_S_AXI_ADDR_WIDTH = `C_S_AXI_ADDR_WIDTH,
    parameter integer C_S_AXI_DATA_WIDTH = `C_S_AXI_DATA_WIDTH,
    parameter integer C_S_AXI_MEM_DEPTH  = `C_S_AXI_MEM_DEPTH
)(
    input logic S_AXI_ACLK,
    input logic S_AXI_ARESETN
);

  localparam integer STRB_WIDTH = C_S_AXI_DATA_WIDTH / 8;
  localparam integer ADDR_LSB   = $clog2(STRB_WIDTH);

  // Write Address Channel (AW)
  logic [C_S_AXI_ID_WIDTH-1:0]   S_AXI_AWID;
  logic [C_S_AXI_ADDR_WIDTH-1:0] S_AXI_AWADDR;
  logic [7:0]                    S_AXI_AWLEN;
  logic [2:0]                    S_AXI_AWSIZE;
  logic [1:0]                    S_AXI_AWBURST;
  logic                          S_AXI_AWLOCK;
  logic [3:0]                    S_AXI_AWCACHE;
  logic [2:0]                    S_AXI_AWPROT;
  logic [3:0]                    S_AXI_AWQOS;
  logic                          S_AXI_AWVALID;
  logic                          S_AXI_AWREADY;

  // Write Data Channel (W)
  logic [C_S_AXI_DATA_WIDTH-1:0] S_AXI_WDATA;
  logic [STRB_WIDTH-1:0]         S_AXI_WSTRB;
  logic                          S_AXI_WLAST;
  logic                          S_AXI_WVALID;
  logic                          S_AXI_WREADY;

  // Write Response Channel (B)
  logic [C_S_AXI_ID_WIDTH-1:0]   S_AXI_BID;
  logic [1:0]                    S_AXI_BRESP;
  logic                          S_AXI_BVALID;
  logic                          S_AXI_BREADY;

  // Read Address Channel (AR)
  logic [C_S_AXI_ID_WIDTH-1:0]   S_AXI_ARID;
  logic [C_S_AXI_ADDR_WIDTH-1:0] S_AXI_ARADDR;
  logic [7:0]                    S_AXI_ARLEN;
  logic [2:0]                    S_AXI_ARSIZE;
  logic [1:0]                    S_AXI_ARBURST;
  logic                          S_AXI_ARLOCK;
  logic [3:0]                    S_AXI_ARCACHE;
  logic [2:0]                    S_AXI_ARPROT;
  logic [3:0]                    S_AXI_ARQOS;
  logic                          S_AXI_ARVALID;
  logic                          S_AXI_ARREADY;

  // Read Data Channel (R)
  logic [C_S_AXI_ID_WIDTH-1:0]   S_AXI_RID;
  logic [C_S_AXI_DATA_WIDTH-1:0] S_AXI_RDATA;
  logic [1:0]                    S_AXI_RRESP;
  logic                          S_AXI_RLAST;
  logic                          S_AXI_RVALID;
  logic                          S_AXI_RREADY;

  // Master-side VALID/READY start at 0 so the DUT never sees X after reset
  initial begin
    S_AXI_AWVALID = 1'b0;
    S_AXI_WVALID  = 1'b0;
    S_AXI_BREADY  = 1'b0;
    S_AXI_ARVALID = 1'b0;
    S_AXI_RREADY  = 1'b0;
  end

  // Driver clocking block (master drives AW/W/AR, samples B/R)
  clocking driver_cb @(posedge S_AXI_ACLK);
    default input #1step output #0;
    output S_AXI_AWID, S_AXI_AWADDR, S_AXI_AWLEN, S_AXI_AWSIZE, S_AXI_AWBURST;
    output S_AXI_AWLOCK, S_AXI_AWCACHE, S_AXI_AWPROT, S_AXI_AWQOS, S_AXI_AWVALID;
    output S_AXI_WDATA, S_AXI_WSTRB, S_AXI_WLAST, S_AXI_WVALID;
    output S_AXI_BREADY;
    output S_AXI_ARID, S_AXI_ARADDR, S_AXI_ARLEN, S_AXI_ARSIZE, S_AXI_ARBURST;
    output S_AXI_ARLOCK, S_AXI_ARCACHE, S_AXI_ARPROT, S_AXI_ARQOS, S_AXI_ARVALID;
    output S_AXI_RREADY;
    input  S_AXI_AWREADY, S_AXI_WREADY, S_AXI_BID, S_AXI_BRESP, S_AXI_BVALID;
    input  S_AXI_ARREADY, S_AXI_RID, S_AXI_RDATA, S_AXI_RRESP, S_AXI_RLAST, S_AXI_RVALID;
  endclocking

  // Monitor clocking block (samples everything, drives nothing)
  clocking monitor_cb @(posedge S_AXI_ACLK);
    default input #1step;
    input S_AXI_ARESETN;
    input S_AXI_AWID, S_AXI_AWADDR, S_AXI_AWLEN, S_AXI_AWSIZE, S_AXI_AWBURST;
    input S_AXI_AWLOCK, S_AXI_AWCACHE, S_AXI_AWPROT, S_AXI_AWQOS, S_AXI_AWVALID;
    input S_AXI_WDATA, S_AXI_WSTRB, S_AXI_WLAST, S_AXI_WVALID;
    input S_AXI_BID, S_AXI_BRESP, S_AXI_BVALID, S_AXI_BREADY;
    input S_AXI_ARID, S_AXI_ARADDR, S_AXI_ARLEN, S_AXI_ARSIZE, S_AXI_ARBURST;
    input S_AXI_ARLOCK, S_AXI_ARCACHE, S_AXI_ARPROT, S_AXI_ARQOS, S_AXI_ARVALID;
    input S_AXI_RID, S_AXI_RDATA, S_AXI_RRESP, S_AXI_RLAST, S_AXI_RVALID, S_AXI_RREADY;
    input S_AXI_AWREADY, S_AXI_WREADY, S_AXI_ARREADY;
  endclocking

  modport driver_mp (
    clocking driver_cb,
    input S_AXI_ACLK, S_AXI_ARESETN
  );

  modport monitor_mp (
    clocking monitor_cb,
    input S_AXI_ACLK, S_AXI_ARESETN
  );

  modport dut_mp (
    input  S_AXI_ACLK, S_AXI_ARESETN,
    input  S_AXI_AWID, S_AXI_AWADDR, S_AXI_AWLEN, S_AXI_AWSIZE, S_AXI_AWBURST,
    input  S_AXI_AWLOCK, S_AXI_AWCACHE, S_AXI_AWPROT, S_AXI_AWQOS, S_AXI_AWVALID,
    output S_AXI_AWREADY,
    input  S_AXI_WDATA, S_AXI_WSTRB, S_AXI_WLAST, S_AXI_WVALID,
    output S_AXI_WREADY,
    output S_AXI_BID, S_AXI_BRESP, S_AXI_BVALID,
    input  S_AXI_BREADY,
    input  S_AXI_ARID, S_AXI_ARADDR, S_AXI_ARLEN, S_AXI_ARSIZE, S_AXI_ARBURST,
    input  S_AXI_ARLOCK, S_AXI_ARCACHE, S_AXI_ARPROT, S_AXI_ARQOS, S_AXI_ARVALID,
    output S_AXI_ARREADY,
    output S_AXI_RID, S_AXI_RDATA, S_AXI_RRESP, S_AXI_RLAST, S_AXI_RVALID,
    input  S_AXI_RREADY
  );

  // NOTE: assertions are bound to axi4_slave in axi4_bind.sv, not here.

endinterface

`endif // AXI4_IF_SV

// axi4_whitebox_assertions

// axi4_whitebox_assertions.sv
// White-box assertions bound onto axi4_slave. Every port name below must
// exist in axi4_slave (bind uses .*).
// A-004,A-007,A-010,A-011,A-012,A-013,A-020,A-021,A-022,A-023,A-024,
// A-025,A-027,A-028,A-031

`timescale 1ns/1ps

`ifndef AXI4_WHITEBOX_ASSERTIONS_SV
`define AXI4_WHITEBOX_ASSERTIONS_SV

`include "uvm_macros.svh"

module axi4_whitebox_assertions
  import uvm_pkg::*;
#(
    parameter integer C_S_AXI_ID_WIDTH   = 4,
    parameter integer C_S_AXI_ADDR_WIDTH = 32,
    parameter integer C_S_AXI_DATA_WIDTH = 32,
    parameter integer C_S_AXI_MEM_DEPTH  = 1024,
    parameter integer MEM_ADDR_BITS      = $clog2(C_S_AXI_MEM_DEPTH)  // do not override
)(
    input logic                                S_AXI_ACLK,
    input logic                                S_AXI_ARESETN,

    // Interface signals (all INPUTS here - this module only observes)
    input logic                                S_AXI_AWREADY,
    input logic                                S_AXI_WVALID,
    input logic                                S_AXI_WREADY,
    input logic [C_S_AXI_DATA_WIDTH-1:0]       S_AXI_WDATA,
    input logic [(C_S_AXI_DATA_WIDTH/8)-1:0]   S_AXI_WSTRB,
    input logic [1:0]                          S_AXI_BRESP,
    input logic                                S_AXI_BVALID,
    input logic                                S_AXI_BREADY,
    input logic                                S_AXI_ARREADY,
    input logic [C_S_AXI_DATA_WIDTH-1:0]       S_AXI_RDATA,
    input logic                                S_AXI_RVALID,
    input logic                                S_AXI_RREADY,

    // DUT-internal signals
    input logic [1:0]                          wr_state,
    input logic [C_S_AXI_ADDR_WIDTH-1:0]       wr_addr_lat,
    input logic [7:0]                          wr_len_lat,
    input logic [2:0]                          wr_size_lat,
    input logic [1:0]                          wr_burst_lat,
    input logic [7:0]                          wr_beat_cnt,
    input logic [MEM_ADDR_BITS-1:0]            wr_mem_index,
    input logic                                wr_addr_in_range,

    input logic                                rd_state,
    input logic [C_S_AXI_ADDR_WIDTH-1:0]       rd_addr_lat,
    input logic [7:0]                          rd_len_lat,
    input logic [2:0]                          rd_size_lat,
    input logic [1:0]                          rd_burst_lat,
    input logic [7:0]                          rd_beat_cnt,
    input logic [MEM_ADDR_BITS-1:0]            rd_mem_index,
    input logic                                rd_addr_in_range,

    // DUT memory array
    input logic [C_S_AXI_DATA_WIDTH-1:0]       mem [0:C_S_AXI_MEM_DEPTH-1]
);

    // -------------------------------------------------------------------------
    // Local parameters
    // -------------------------------------------------------------------------
    localparam integer STRB_WIDTH = C_S_AXI_DATA_WIDTH / 8;
    localparam integer ADDR_LSB   = $clog2(STRB_WIDTH);

    localparam logic [1:0] WR_IDLE = 2'd0, WR_DATA = 2'd1, WR_RESP = 2'd2;
    localparam logic       RD_IDLE = 1'b0, RD_DATA = 1'b1;

    localparam logic [C_S_AXI_ADDR_WIDTH-1:0] ONE = 1;

    default clocking cb @(posedge S_AXI_ACLK); endclocking
    default disable iff (!S_AXI_ARESETN);

    wire w_hs = S_AXI_WVALID && S_AXI_WREADY;
    wire r_hs = S_AXI_RVALID && S_AXI_RREADY;

    // -------------------------------------------------------------------------
    // Independent WRAP next-address model (AXI4 spec A3.4.1)
    // -------------------------------------------------------------------------
    function automatic logic [C_S_AXI_ADDR_WIDTH-1:0] exp_wrap_next(
        input logic [C_S_AXI_ADDR_WIDTH-1:0] cur,
        input logic [2:0]                    size,
        input logic [7:0]                    len
    );
        logic [C_S_AXI_ADDR_WIDTH-1:0] nbytes, wsize, wbound, inc;
        begin
            nbytes = ONE << size;
            wsize  = nbytes * (len + 1);
            wbound = cur & ~(wsize - 1);
            inc    = cur + nbytes;
            exp_wrap_next = (inc >= (wbound + wsize)) ? wbound : inc;
        end
    endfunction

    wire [C_S_AXI_ADDR_WIDTH-1:0] wr_wrap_next = exp_wrap_next(wr_addr_lat, wr_size_lat, wr_len_lat);
    wire [C_S_AXI_ADDR_WIDTH-1:0] rd_wrap_next = exp_wrap_next(rd_addr_lat, rd_size_lat, rd_len_lat);

    // -------------------------------------------------------------------------
    // Helper state
    // -------------------------------------------------------------------------
    // Previous-cycle in-range write (used to exclude read/write same-word races)
    logic                        wr_hs_ir_q;
    logic [MEM_ADDR_BITS-1:0]    wr_idx_q;
    // Any beat of the current write burst was out of range
    logic                        wr_err_seen;

    always_ff @(posedge S_AXI_ACLK) begin
        if (!S_AXI_ARESETN) begin
            wr_hs_ir_q  <= 1'b0;
            wr_idx_q    <= '0;
            wr_err_seen <= 1'b0;
        end else begin
            wr_hs_ir_q <= w_hs && wr_addr_in_range;
            wr_idx_q   <= wr_mem_index;
            if (S_AXI_BVALID && S_AXI_BREADY)  wr_err_seen <= 1'b0;
            else if (w_hs && !wr_addr_in_range) wr_err_seen <= 1'b1;
        end
    end

    // =========================================================================
    // A-004: out-of-range write beat must not modify memory
    // =========================================================================
    // A-004
    A_004: assert property (
        w_hs && !wr_addr_in_range |=>
            mem[$past(wr_mem_index)] === $past(mem[wr_mem_index]))
        else `uvm_error("A-004", "Out-of-range write modified memory");

    // =========================================================================
    // A-007: accepted read beat returns the memory word at that beat's address
    // (skipped when a write to the same word was accepted in the previous cycle)
    // =========================================================================
    // A-007
    A_007: assert property (
        r_hs && rd_addr_in_range && !(wr_hs_ir_q && (wr_idx_q == rd_mem_index)) |->
            S_AXI_RDATA === mem[rd_mem_index])
        else `uvm_error("A-007", "RDATA does not match memory content at the beat address");

    // =========================================================================
    // A-010: WRAP address sequence
    // A-011: INCR address sequence
    // A-012: FIXED address constant
    // (checked on the latched address after each accepted, non-final beat)
    // =========================================================================
    // A-010
    A_010_WR: assert property (
        w_hs && wr_beat_cnt != 8'd0 && wr_burst_lat == 2'b10 |=>
            wr_addr_lat == $past(wr_wrap_next))
        else `uvm_error("A-010", "WRAP write address sequence incorrect");

    // A-010
    A_010_RD: assert property (
        r_hs && rd_beat_cnt != 8'd0 && rd_burst_lat == 2'b10 |=>
            rd_addr_lat == $past(rd_wrap_next))
        else `uvm_error("A-010", "WRAP read address sequence incorrect");

    // A-011
    A_011_WR: assert property (
        w_hs && wr_beat_cnt != 8'd0 && wr_burst_lat == 2'b01 |=>
            wr_addr_lat == $past(wr_addr_lat) + (ONE << $past(wr_size_lat)))
        else `uvm_error("A-011", "INCR write address must advance by transfer size");

    // A-011
    A_011_RD: assert property (
        r_hs && rd_beat_cnt != 8'd0 && rd_burst_lat == 2'b01 |=>
            rd_addr_lat == $past(rd_addr_lat) + (ONE << $past(rd_size_lat)))
        else `uvm_error("A-011", "INCR read address must advance by transfer size");

    // A-012
    A_012_WR: assert property (
        w_hs && wr_beat_cnt != 8'd0 && wr_burst_lat == 2'b00 |=>
            wr_addr_lat == $past(wr_addr_lat))
        else `uvm_error("A-012", "FIXED write burst address must remain constant");

    // A-012
    A_012_RD: assert property (
        r_hs && rd_beat_cnt != 8'd0 && rd_burst_lat == 2'b00 |=>
            rd_addr_lat == $past(rd_addr_lat))
        else `uvm_error("A-012", "FIXED read burst address must remain constant");

    // =========================================================================
    // A-013: WSTRB honoured per byte lane (strobed lane <- WDATA, others unchanged)
    // =========================================================================
    generate
        for (genvar lane = 0; lane < STRB_WIDTH; lane++) begin : g_lane
            // A-013
            A_013: assert property (
                w_hs && wr_addr_in_range |=>
                    mem[$past(wr_mem_index)][lane*8 +: 8] ===
                        ($past(S_AXI_WSTRB[lane]) ? $past(S_AXI_WDATA[lane*8 +: 8])
                                                  : $past(mem[wr_mem_index][lane*8 +: 8])))
                else `uvm_error("A-013", $sformatf("WSTRB byte-lane %0d violated", lane));
        end
    endgenerate

    // =========================================================================
    // A-020: RVALID is high in RD_DATA (from the 2nd RD_DATA cycle on, since
    //        RVALID is registered) and only in RD_DATA
    // =========================================================================
    // A-020
    A_020_A: assert property (
        (rd_state == RD_DATA) ##1 (rd_state == RD_DATA) |-> S_AXI_RVALID)
        else `uvm_error("A-020", "RVALID must be asserted while in RD_DATA");

    // A-020
    A_020_B: assert property (
        S_AXI_RVALID |-> rd_state == RD_DATA)
        else `uvm_error("A-020", "RVALID asserted outside RD_DATA");

    // =========================================================================
    // A-021 / A-022 / A-023: READY only in the matching FSM state
    // =========================================================================
    // A-021
    A_021: assert property (S_AXI_AWREADY |-> wr_state == WR_IDLE)
        else `uvm_error("A-021", "AWREADY only in WR_IDLE");

    // A-022
    A_022: assert property (S_AXI_WREADY |-> wr_state == WR_DATA)
        else `uvm_error("A-022", "WREADY only in WR_DATA");

    // A-023
    A_023: assert property (S_AXI_ARREADY |-> rd_state == RD_IDLE)
        else `uvm_error("A-023", "ARREADY only in RD_IDLE");

    // =========================================================================
    // A-024: beat counters decrement exactly once per accepted beat
    // =========================================================================
    // A-024
    A_024_WR_DEC: assert property (
        w_hs && wr_beat_cnt != 8'd0 |=> wr_beat_cnt == $past(wr_beat_cnt) - 8'd1)
        else `uvm_error("A-024", "wr_beat_cnt must decrement by 1 per accepted write beat");

    // A-024
    A_024_WR_END: assert property (
        w_hs && wr_beat_cnt == 8'd0 |=> wr_state == WR_RESP)
        else `uvm_error("A-024", "Final write beat must move FSM to WR_RESP");

    // A-024
    A_024_WR_HOLD: assert property (
        wr_state == WR_DATA && !w_hs |=> $stable(wr_beat_cnt))
        else `uvm_error("A-024", "wr_beat_cnt changed without an accepted write beat");

    // A-024
    A_024_RD_DEC: assert property (
        r_hs && rd_beat_cnt != 8'd0 |=> rd_beat_cnt == $past(rd_beat_cnt) - 8'd1)
        else `uvm_error("A-024", "rd_beat_cnt must decrement by 1 per accepted read beat");

    // A-024
    A_024_RD_END: assert property (
        r_hs && rd_beat_cnt == 8'd0 |=> rd_state == RD_IDLE)
        else `uvm_error("A-024", "Final read beat must return FSM to RD_IDLE");

    // =========================================================================
    // A-025: any out-of-range beat in a write burst forces BRESP = SLVERR
    // =========================================================================
    // A-025
    A_025: assert property (
        S_AXI_BVALID && wr_err_seen |-> S_AXI_BRESP == 2'b10)
        else `uvm_error("A-025", "SLVERR must be sticky for the whole write burst");

    // =========================================================================
    // A-027: mem index derived from the latched address
    // =========================================================================
    // A-027
    A_027_WR: assert property (
        wr_mem_index == wr_addr_lat[ADDR_LSB +: MEM_ADDR_BITS])
        else `uvm_error("A-027", "wr_mem_index not derived correctly from wr_addr_lat");

    // A-027
    A_027_RD: assert property (
        rd_mem_index == rd_addr_lat[ADDR_LSB +: MEM_ADDR_BITS])
        else `uvm_error("A-027", "rd_mem_index not derived correctly from rd_addr_lat");

    // =========================================================================
    // A-028: WSTRB all-zero write beat must not change memory
    // =========================================================================
    // A-028
    A_028: assert property (
        w_hs && (S_AXI_WSTRB == '0) |=>
            mem[$past(wr_mem_index)] === $past(mem[wr_mem_index]))
        else `uvm_error("A-028", "WSTRB==0 write modified memory");

    // =========================================================================
    // A-031: in-range decode: upper address bits above the memory must be zero
    // =========================================================================
    // A-031
    A_031_WR: assert property (
        wr_addr_in_range == ((wr_addr_lat >> (ADDR_LSB + MEM_ADDR_BITS)) == '0))
        else `uvm_error("A-031", "wr_addr_in_range decode incorrect");

    // A-031
    A_031_RD: assert property (
        rd_addr_in_range == ((rd_addr_lat >> (ADDR_LSB + MEM_ADDR_BITS)) == '0))
        else `uvm_error("A-031", "rd_addr_in_range decode incorrect");

endmodule

`endif // AXI4_WHITEBOX_ASSERTIONS_SV

