// class axi4_wlast_mismatch_seq

// axi4_wlast_mismatch_seq.sv
// File        : axi4_wlast_mismatch_seq.sv
// Description : WLAST timing mismatch sequence for AXI4 slave testbench.
//               Tests cases where WLAST is asserted early or late
//               relative to the actual burst length (TC-020..TC-021).
// Author      : Verification Engineer
// Date        : 2026-09-17
// Revision    : 1.0

`ifndef AXI4_WLAST_MISMATCH_SEQ_SV
`define AXI4_WLAST_MISMATCH_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_wlast_mismatch_seq extends uvm_sequence #(axi4_seq_item);

  // -----------------------------------------------------------------------
  // Configuration: WLAST mismatch mode
  //   0 = WLAST early (asserted before last beat)
  //   1 = WLAST late (asserted after last beat)
  // -----------------------------------------------------------------------
  rand bit [1:0] wlast_mode;

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_object_utils(axi4_wlast_mismatch_seq)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_wlast_mismatch_seq");
    super.new(name);
    wlast_mode = 2'b00;
  endfunction

  // -----------------------------------------------------------------------
  // Body: send write transactions with WLAST mismatch
  // -----------------------------------------------------------------------
  virtual task body();
    axi4_seq_item tx;
    int unsigned num_beats;

    `uvm_info("SEQ_WLST", "Starting WLAST mismatch sequence", UVM_MEDIUM)

    // Test all burst types with WLAST mismatch
    for (int burst = 0; burst < 3; burst++) begin
      bit [1:0] burst_type;
      case (burst)
        0: burst_type = `BURST_FIXED;
        1: burst_type = `BURST_INCR;
        2: burst_type = `BURST_WRAP;
      endcase

      for (int len_idx = 0; len_idx < 2; len_idx++) begin
        bit [7:0] len;
        if (len_idx == 0) len = 8'd0;       // Single beat
        else              len = 8'd3;       // 4 beats

        tx = axi4_seq_item::type_id::create($sformatf("tx_b%0d_l%0d", burst, len));

        // Setup transaction
        tx.ax_id     = burst[1:0];
        tx.ax_addr   = (len == 8'd0) ? 32'h00000000 : 32'h00001000;
        tx.ax_len    = len;
        tx.ax_size   = 3'd2;    // 4-byte transfer
        tx.ax_burst  = burst_type;
        tx.ax_lock   = 1'b0;
        tx.ax_cache  = 4'b0000;
        tx.ax_prot   = 3'b000;
        tx.is_write  = 1'b1;
        tx.w_strb    = 4'hF;
        tx.w_last    = 1'b1;
        tx.w_data    = {8'd0, $random};

        num_beats = len + 1;

        // Apply WLAST mismatch
        if (wlast_mode == 2'b00) begin
          // WLAST early: assert WLAST on first beat
          tx.w_last = 1'b1;
          `uvm_info("SEQ_WLST", "WLAST early mode", UVM_LOW)
        end else if (wlast_mode == 2'b01) begin
          // WLAST late: deassert WLAST until final beat
          tx.w_last = 1'b0;
          `uvm_info("SEQ_WLST", "WLAST late mode", UVM_LOW)
        end

        `uvm_info("SEQ_WLST", $sformatf(
          "Send wlast_mismatch[%0d]: burst=%s len=%0d wlast=%0d",
          burst, tx.burst_name(), tx.ax_len, tx.w_last), UVM_LOW)

        // Send to driver
        start_item(tx);
        assert(tx.randomize());
        finish_item(tx);
      end
    end

    `uvm_info("SEQ_WLST", "WLAST mismatch sequence complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_WLAST_MISMATCH_SEQ_SV

// class axi4_wrap_len_seq

// axi4_wrap_len_seq.sv
// File        : axi4_wrap_len_seq.sv
// Description : WRAP burst sequence with specific burst lengths for TC-039/TC-040.
//               Supports length 2 (ax_len=1) and length 16 (ax_len=15).
//               Tests wrap boundary wrapping calculation and addressing.
// Author      : Verification Engineer
// Date        : 2026-09-18
// Revision    : 1.0

`ifndef AXI4_WRAP_LEN_SEQ_SV
`define AXI4_WRAP_LEN_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_wrap_len_seq extends uvm_sequence #(axi4_seq_item);

  // -----------------------------------------------------------------------
  // Configuration knobs
  // -----------------------------------------------------------------------
  rand bit [7:0]  target_len;   // 8'd1 for len 2, 8'd15 for len 16
  rand bit [31:0] base_addr;
  rand bit [3:0]  trans_id;

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_object_utils(axi4_wrap_len_seq)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_wrap_len_seq");
    super.new(name);
    target_len = 8'd1;  // Default: length 2 (ax_len = 1)
    base_addr = 32'h0000_0020;
    trans_id = 4'h0;
  endfunction

  // -----------------------------------------------------------------------
  // Body: WRAP Write then Read-back
  // -----------------------------------------------------------------------
  virtual task body();
    axi4_seq_item tx;
    int wrap_size_bytes;
    bit [31:0] aligned_addr;

    // WRAP burst constraints:
    // 1. Length must be 2, 4, 8, or 16 (ax_len in {1, 3, 7, 15})
    // 2. Start address must be aligned to the total burst size: (AxLEN + 1) * 2^AxSIZE
    wrap_size_bytes = (target_len + 1) * 4; // 4-byte size (ax_size=2)
    aligned_addr = (base_addr / wrap_size_bytes) * wrap_size_bytes;

    `uvm_info("SEQ_WRAP_LEN", $sformatf(
      "Starting WRAP burst test: len=%0d (beats=%0d) addr=0x%08h",
      target_len, target_len+1, aligned_addr), UVM_MEDIUM)

    // 1. WRAP Write Burst
    tx = axi4_seq_item::type_id::create("tx_wrap_write");
    assert(tx.randomize() with {
      is_write == 1'b1;
      ax_addr == aligned_addr;
      ax_id == trans_id;
      ax_len == target_len;
      ax_size == 3'b010;  // 4 bytes
      ax_burst == `BURST_WRAP;
      ax_lock == 1'b0;
      ax_cache == 4'b0000;
      ax_prot == 3'b000;
      ax_qos == 4'b0000;
    });

    tx.w_data = 32'hDEAD_0001;
    tx.w_strb = 4'b1111;
    tx.w_last = 1'b1;

    `uvm_info("SEQ_WRAP_LEN", $sformatf("Driving WRAP Write: addr=0x%08h len=%0d", aligned_addr, target_len+1), UVM_LOW)
    start_item(tx);
    finish_item(tx);

    // 2. WRAP Read Burst
    tx = axi4_seq_item::type_id::create("tx_wrap_read");
    assert(tx.randomize() with {
      is_write == 1'b0;
      ax_addr == aligned_addr;
      ax_id == trans_id;
      ax_len == target_len;
      ax_size == 3'b010;  // 4 bytes
      ax_burst == `BURST_WRAP;
      ax_lock == 1'b0;
      ax_cache == 4'b0000;
      ax_prot == 3'b000;
      ax_qos == 4'b0000;
    });

    `uvm_info("SEQ_WRAP_LEN", $sformatf("Driving WRAP Read: addr=0x%08h len=%0d", aligned_addr, target_len+1), UVM_LOW)
    start_item(tx);
    finish_item(tx);

    `uvm_info("SEQ_WRAP_LEN", "WRAP burst sequence complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_WRAP_LEN_SEQ_SV

// class axi4_write_seq

// axi4_write_seq.sv
// File        : axi4_write_seq.sv
// Description : Base write sequence for AXI4 slave testbench.
//               Sends randomized write transactions with valid
//               burst types, lengths, and sizes.
// Author      : Verification Engineer
// Date        : 2026-09-17
// Revision    : 1.0

`ifndef AXI4_WRITE_SEQ_SV
`define AXI4_WRITE_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_write_seq extends uvm_sequence #(axi4_seq_item);

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_object_utils(axi4_write_seq)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_write_seq");
    super.new(name);
  endfunction

  // -----------------------------------------------------------------------
  // Body: send randomized write transactions
  // -----------------------------------------------------------------------
  virtual task body();
  axi4_seq_item tx;
  int unsigned num_trans = 10;
  int unsigned num_bytes;

  `uvm_info("SEQ_W", $sformatf("Starting write sequence: %0d transactions",
    num_trans), UVM_MEDIUM)

  for (int i = 0; i < num_trans; i++) begin
    tx = axi4_seq_item::type_id::create("tx");
    tx.is_write = 1'b1;

    // Randomize write parameters (single call - constraints only, no
    // second unconstrained randomize afterward)
    assert(tx.randomize() with {
      ax_id    < 16;
      ax_addr  < (1 << 30);              // 1GB address space
      ax_len   < 16;                     // 1-16 beats
      ax_size  inside {0, 1, 2};         // 1B/2B/4B only - matches 32-bit bus
      ax_burst inside {`BURST_FIXED, `BURST_INCR, `BURST_WRAP};
      ax_lock  == 1'b0;
      ax_cache inside {4'b0000, 4'b0010, 4'b0100};
      ax_prot  inside {3'b000, 3'b001};

      // WRAP bursts must use legal lengths per AXI4 spec
      (ax_burst == `BURST_WRAP) -> ax_len inside {1, 3, 7, 15};
    });

    // Derive a valid byte-strobe mask from the actual transfer size
    num_bytes = (1 << tx.ax_size);
    tx.w_strb = (num_bytes >= `C_S_AXI_STRB_WIDTH) ?
                  {`C_S_AXI_STRB_WIDTH{1'b1}} : ((1 << num_bytes) - 1);
    tx.w_last = 1'b1;

    `uvm_info("SEQ_W", $sformatf("Send write[%0d]: addr=0x%0h len=%0d size=%0d burst=%s",
      i, tx.ax_addr, tx.ax_len, tx.ax_size, tx.burst_name()), UVM_LOW)

    // Start item, send to driver, finish item - randomize happens ONCE,
    // before start_item, not again here
    start_item(tx);
    finish_item(tx);
  end

    `uvm_info("SEQ_W", "Write sequence complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_WRITE_SEQ_SV

// class axi4_wstrb_zero_seq

// axi4_wstrb_zero_seq.sv
// File        : axi4_wstrb_zero_seq.sv
// Description : WSTRB all-zero write sequence for TC-033.
//               Writes with WSTRB = 4'b0000 to verify no memory update occurs.
//               Initializes memory, writes with all-zero strobes, reads back to verify.
// Author      : Verification Engineer
// Date        : 2026-09-18
// Revision    : 1.0

`ifndef AXI4_WSTRB_ZERO_SEQ_SV
`define AXI4_WSTRB_ZERO_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_wstrb_zero_seq extends uvm_sequence #(axi4_seq_item);

  // -----------------------------------------------------------------------
  // Configuration knobs
  // -----------------------------------------------------------------------
  rand bit [31:0] target_addr;
  rand bit [3:0]  trans_id;
  rand bit [31:0] init_data;
  rand bit [31:0] attempted_data;

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_object_utils(axi4_wstrb_zero_seq)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_wstrb_zero_seq");
    super.new(name);
    target_addr = 32'h00000040;
    trans_id = 4'h0;
    init_data = 32'hAAAA_5555;
    attempted_data = 32'h1234_5678;
  endfunction

  // -----------------------------------------------------------------------
  // Body: 1. Init write with valid strobes
  //       2. Write with WSTRB=0000
  //       3. Read back to confirm data didn't change
  // -----------------------------------------------------------------------
  virtual task body();
    axi4_seq_item tx;

    `uvm_info("SEQ_WSTRB_ZERO", $sformatf(
      "Starting WSTRB=0 test on addr=0x%08h", target_addr), UVM_MEDIUM)

    // Step 1: Initialize target word with known data
    tx = axi4_seq_item::type_id::create("tx_init_write");
    assert(tx.randomize() with {
      is_write == 1'b1;
      ax_addr == target_addr;
      ax_id == trans_id;
      ax_len == 8'd0;
      ax_size == 3'b010;
      ax_burst == `BURST_INCR;
      ax_lock == 1'b0;
      ax_cache == 4'b0000;
      ax_prot == 3'b000;
      ax_qos == 4'b0000;
    });
    tx.w_data = init_data;
    tx.w_strb = 4'b1111;
    tx.w_last = 1'b1;

    `uvm_info("SEQ_WSTRB_ZERO", $sformatf("Step 1: Init write data=0x%08h", init_data), UVM_LOW)
    start_item(tx);
    finish_item(tx);

    // Step 2: Attempt write with all-zero WSTRB
    tx = axi4_seq_item::type_id::create("tx_zero_wstrb_write");
    assert(tx.randomize() with {
      is_write == 1'b1;
      ax_addr == target_addr;
      ax_id == trans_id;
      ax_len == 8'd0;
      ax_size == 3'b010;
      ax_burst == `BURST_INCR;
      ax_lock == 1'b0;
      ax_cache == 4'b0000;
      ax_prot == 3'b000;
      ax_qos == 4'b0000;
    });
    tx.w_data = attempted_data;
    tx.w_strb = 4'b0000;  // ALL ZERO STROBE
    tx.w_last = 1'b1;

    `uvm_info("SEQ_WSTRB_ZERO", $sformatf(
      "Step 2: Write with WSTRB=4'b0000, attempted_data=0x%08h", attempted_data), UVM_LOW)
    start_item(tx);
    finish_item(tx);

    // Step 3: Read back and verify data unchanged
    tx = axi4_seq_item::type_id::create("tx_verify_read");
    assert(tx.randomize() with {
      is_write == 1'b0;
      ax_addr == target_addr;
      ax_id == trans_id;
      ax_len == 8'd0;
      ax_size == 3'b010;
      ax_burst == `BURST_INCR;
      ax_lock == 1'b0;
      ax_cache == 4'b0000;
      ax_prot == 3'b000;
      ax_qos == 4'b0000;
    });

    `uvm_info("SEQ_WSTRB_ZERO", "Step 3: Read back to verify unchanged data", UVM_LOW)
    start_item(tx);
    finish_item(tx);

    `uvm_info("SEQ_WSTRB_ZERO", "WSTRB=0 sequence complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_WSTRB_ZERO_SEQ_SV


// class axi4_addr_map_seq

// axi4_addr_map_seq.sv
// File        : axi4_addr_map_seq.sv
// Description : Address map sequence for AXI4 slave testbench.
//               Generates address map patterns for Layer 1 tests,
//               testing all regions of memory with systematic address
//               patterns.
// Author      : Verification Engineer
// Date        : 2026-09-17
// Revision    : 1.1  (fixed: a trailing assert(tx.randomize()) right
//                     before finish_item() re-randomized the ENTIRE item,
//                     wiping out the INCREMENTAL/BACK_FILL/SKIP address
//                     just computed, and the RANDOM pattern's own
//                     constrained randomize(). Removed the trailing call.)

`ifndef AXI4_ADDR_MAP_SEQ_SV
`define AXI4_ADDR_MAP_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_addr_map_seq extends uvm_sequence #(axi4_seq_item);

  typedef enum logic [3:0] {
    ADDR_REGION_0 = 4'd0, ADDR_REGION_1 = 4'd1, ADDR_REGION_2 = 4'd2,
    ADDR_REGION_3 = 4'd3, ADDR_REGION_4 = 4'd4, ADDR_REGION_5 = 4'd5,
    ADDR_REGION_6 = 4'd6, ADDR_REGION_7 = 4'd7
  } addr_region_e;

  rand addr_region_e region;
  rand bit [31:0] base_addr;
  rand bit [7:0]  burst_len;
  rand bit [2:0]  burst_size;
  rand bit [1:0]  burst_type;
  rand bit        is_write;
  rand int unsigned num_transactions;

  typedef enum logic [2:0] {
    ADDR_PATTERN_INCREMENTAL = 3'd0, ADDR_PATTERN_RANDOM = 3'd1,
    ADDR_PATTERN_BACK_FILL   = 3'd2, ADDR_PATTERN_SKIP   = 3'd3
  } addr_pattern_e;

  rand addr_pattern_e addr_pattern;

  `uvm_object_utils(axi4_addr_map_seq)

  function new(string name = "axi4_addr_map_seq");
    super.new(name);
    region           = ADDR_REGION_0;
    base_addr        = 32'h00000000;
    burst_len        = 8'd0;
    burst_size       = 3'd2;
    burst_type       = `BURST_INCR;
    is_write         = 1'b1;
    num_transactions = 20;
    addr_pattern     = ADDR_PATTERN_INCREMENTAL;
  endfunction

  virtual task body();
    axi4_seq_item tx;
    bit [31:0] addr;
    int i;

    `uvm_info("SEQ_AM", $sformatf(
      "Starting address map: region=%0d pattern=%0d num=%0d",
      region, addr_pattern, num_transactions), UVM_MEDIUM)

    addr = base_addr;

    for (i = 0; i < num_transactions; i++) begin
      tx = axi4_seq_item::type_id::create($sformatf("tx_%0d", i));

      case (addr_pattern)
        ADDR_PATTERN_INCREMENTAL: begin
          tx.ax_addr = addr;
          addr = addr + (1 << burst_size);
        end
        ADDR_PATTERN_RANDOM: begin
          // This is the ONLY randomize call for this item - fine as-is.
          assert(tx.randomize() with {
            ax_addr inside {[base_addr : base_addr + 1024]};
            ax_addr < (`C_S_AXI_MEM_DEPTH << 2);
            ax_id   < 16;
            ax_len  == burst_len;
            ax_size == burst_size;
            ax_burst == burst_type;
          });
        end
        ADDR_PATTERN_BACK_FILL: begin
          tx.ax_addr = base_addr + 1024 - (i * (1 << burst_size));
        end
        ADDR_PATTERN_SKIP: begin
          tx.ax_addr = base_addr + (i * 2 * (1 << burst_size));
        end
        default: begin
          tx.ax_addr = base_addr;
        end
      endcase

      tx.ax_id    = i[3:0];
      tx.ax_len   = burst_len;
      tx.ax_size  = burst_size;
      tx.ax_burst = burst_type;
      tx.ax_lock  = 1'b0;
      tx.ax_cache = 4'b0000;
      tx.ax_prot  = 3'b000;
      tx.is_write = is_write;
      tx.w_strb   = (~0) << (tx.ax_size[1:0]);
      tx.w_last   = 1'b1;
      tx.w_data   = {8'd0, $random};
      tx.withhold_bready = 1'b0;
      tx.withhold_rready = 1'b0;

      `uvm_info("SEQ_AM", $sformatf(
        "Addr map[%0d]: addr=0x%0h %s pattern=%0d",
        i, tx.ax_addr, tx.is_write ? "WRITE" : "READ", addr_pattern), UVM_LOW)

      // NOTE: removed the blind assert(tx.randomize()) that used to sit
      // here - it was wiping out everything set above, every iteration.
      start_item(tx);
      finish_item(tx);
    end

    `uvm_info("SEQ_AM", "Address map sequence complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_ADDR_MAP_SEQ_SV

// class axi4_adjacent_oor_seq

// axi4_adjacent_oor_seq.sv
// File        : axi4_adjacent_oor_seq.sv
// Description : Adjacent out-of-range address sequence for TC-032.
//               Tests accesses just below memory base and just above memory limit.
//               Base: 0x00000000, Limit: 0x00001000 (1024 words * 4 bytes).
//               Tests addresses: -4 (0xFFFFFFFC), Limit (0x00001000), Limit+4 (0x00001004).
// Author      : Verification Engineer
// Date        : 2026-09-18
// Revision    : 1.0

`ifndef AXI4_ADJACENT_OOR_SEQ_SV
`define AXI4_ADJACENT_OOR_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_adjacent_oor_seq extends uvm_sequence #(axi4_seq_item);

  // -----------------------------------------------------------------------
  // Configuration knobs
  // -----------------------------------------------------------------------
  rand bit [3:0] trans_id;

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_object_utils(axi4_adjacent_oor_seq)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_adjacent_oor_seq");
    super.new(name);
    trans_id = 4'h0;
  endfunction

  // -----------------------------------------------------------------------
  // Body: Test out-of-range addresses adjacent to boundaries
  // -----------------------------------------------------------------------
  virtual task body();
    axi4_seq_item tx;
    bit [31:0] oor_addresses[4];

    // Addresses to test:
    // 0: Just above upper limit (1024 * 4 = 0x1000)
    // 1: One word above upper limit (0x1004)
    // 2: High memory address (0x80000000)
    // 3: Highest possible 32-bit address (0xFFFFFFFC)
    oor_addresses[0] = 32'h00001000;  // First invalid word
    oor_addresses[1] = 32'h00001004;  // Second invalid word
    oor_addresses[2] = 32'h80000000;  // High address
    oor_addresses[3] = 32'hFFFFFFFC;  // Word below 0 (negative/wrap)

    `uvm_info("SEQ_ADJ_OOR", "Starting adjacent out-of-range test sequence", UVM_MEDIUM)

    foreach (oor_addresses[i]) begin
      bit [31:0] test_addr = oor_addresses[i];

      // 1. Out-of-range Write (expect SLVERR, no memory update)
      tx = axi4_seq_item::type_id::create($sformatf("tx_oor_write_%0d", i));
      assert(tx.randomize() with {
        is_write == 1'b1;
        ax_addr == test_addr;
        ax_id == trans_id;
        ax_len == 8'd0;
        ax_size == 3'b010;
        ax_burst == `BURST_INCR;
        ax_lock == 1'b0;
        ax_cache == 4'b0000;
        ax_prot == 3'b000;
        ax_qos == 4'b0000;
      });

      tx.w_data = 32'hDEAD_DEAD;
      tx.w_strb = 4'b1111;
      tx.w_last = 1'b1;

      `uvm_info("SEQ_ADJ_OOR", $sformatf("Driving OOR Write to addr=0x%08h (expect SLVERR)", test_addr), UVM_LOW)
      start_item(tx);
      finish_item(tx);

      // 2. Out-of-range Read (expect SLVERR, data=0)
      tx = axi4_seq_item::type_id::create($sformatf("tx_oor_read_%0d", i));
      assert(tx.randomize() with {
        is_write == 1'b0;
        ax_addr == test_addr;
        ax_id == trans_id;
        ax_len == 8'd0;
        ax_size == 3'b010;
        ax_burst == `BURST_INCR;
        ax_lock == 1'b0;
        ax_cache == 4'b0000;
        ax_prot == 3'b000;
        ax_qos == 4'b0000;
      });

      `uvm_info("SEQ_ADJ_OOR", $sformatf("Driving OOR Read from addr=0x%08h (expect SLVERR, data=0)", test_addr), UVM_LOW)
      start_item(tx);
      finish_item(tx);
    end

    `uvm_info("SEQ_ADJ_OOR", "Adjacent out-of-range sequence complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_ADJACENT_OOR_SEQ_SV

// class axi4_boundary_seq

// axi4_boundary_seq.sv
// File        : axi4_boundary_seq.sv
// Description : Memory boundary access sequence for TC-030/TC-031.
//               Tests access to word 0 (address 0x0000) and word 1023 (address 0x0FFC).
// Author      : Verification Engineer
// Date        : 2026-09-18
// Revision    : 1.0

`ifndef AXI4_BOUNDARY_SEQ_SV
`define AXI4_BOUNDARY_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_boundary_seq extends uvm_sequence #(axi4_seq_item);

  // -----------------------------------------------------------------------
  // Configuration knobs
  // -----------------------------------------------------------------------
  rand bit [31:0] boundary_addr;  // 0x0000 for word 0, 0x0FFC for word 1023
  rand bit        is_write;
  rand bit [31:0] write_data;
  rand bit [3:0]  trans_id;

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_object_utils(axi4_boundary_seq)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_boundary_seq");
    super.new(name);
    boundary_addr = 32'h00000000;
    is_write = 1'b1;
    write_data = 32'hBAADF00D;
    trans_id = 4'h0;
  endfunction

  // -----------------------------------------------------------------------
  // Body: Access boundary word (write then read-back)
  // -----------------------------------------------------------------------
  virtual task body();
    axi4_seq_item tx;

    `uvm_info("SEQ_BOUNDARY", $sformatf(
      "Starting boundary access: addr=0x%08h is_write=%0d",
      boundary_addr, is_write), UVM_MEDIUM)

    // Write transaction
    if (is_write) begin
      tx = axi4_seq_item::type_id::create("tx_write");
      assert(tx.randomize() with {
        is_write == 1'b1;
        ax_addr == boundary_addr;
        ax_id == trans_id;
        ax_len == 8'd0;         // Single beat
        ax_size == 3'b010;      // 4 bytes (32-bit)
        ax_burst == `BURST_INCR;
        ax_lock == 1'b0;
        ax_cache == 4'b0000;
        ax_prot == 3'b000;
        ax_qos == 4'b0000;
      });

      tx.w_data = write_data;
      tx.w_strb = 4'b1111;  // All byte lanes
      tx.w_last = 1'b1;

      `uvm_info("SEQ_BOUNDARY", $sformatf(
        "Write: addr=0x%08h data=0x%08h", boundary_addr, write_data), UVM_LOW)

      start_item(tx);
      finish_item(tx);
    end

    // Read transaction
    tx = axi4_seq_item::type_id::create("tx_read");
    assert(tx.randomize() with {
      is_write == 1'b0;
      ax_addr == boundary_addr;
      ax_id == trans_id;
      ax_len == 8'd0;         // Single beat
      ax_size == 3'b010;      // 4 bytes (32-bit)
      ax_burst == `BURST_INCR;
      ax_lock == 1'b0;
      ax_cache == 4'b0000;
      ax_prot == 3'b000;
      ax_qos == 4'b0000;
    });

    `uvm_info("SEQ_BOUNDARY", $sformatf(
      "Read: addr=0x%08h", boundary_addr), UVM_LOW)

    start_item(tx);
    finish_item(tx);

    `uvm_info("SEQ_BOUNDARY", "Boundary access complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_BOUNDARY_SEQ_SV

// class axi4_byte_lane_seq

// axi4_byte_lane_seq.sv
// File        : axi4_byte_lane_seq.sv
// Description : Single-byte write sequence across each byte lane for TC-034.
//               Initializes a 32-bit word, then writes to each byte lane
//               individually (lanes 0, 1, 2, 3) using single-byte writes
//               with appropriate WSTRB (0001, 0010, 0100, 1000).
// Author      : Verification Engineer
// Date        : 2026-09-18
// Revision    : 1.0

`ifndef AXI4_BYTE_LANE_SEQ_SV
`define AXI4_BYTE_LANE_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_byte_lane_seq extends uvm_sequence #(axi4_seq_item);

  // -----------------------------------------------------------------------
  // Configuration knobs
  // -----------------------------------------------------------------------
  rand bit [31:0] target_word_addr;
  rand bit [3:0]  trans_id;

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_object_utils(axi4_byte_lane_seq)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_byte_lane_seq");
    super.new(name);
    target_word_addr = 32'h00000080;
    trans_id = 4'h0;
  endfunction

  // -----------------------------------------------------------------------
  // Body: Test each byte lane individually
  // -----------------------------------------------------------------------
  virtual task body();
    axi4_seq_item tx;
    bit [7:0] byte_data[4];
    bit [3:0] strobes[4];

    byte_data[0] = 8'h11;
    byte_data[1] = 8'h22;
    byte_data[2] = 8'h33;
    byte_data[3] = 8'h44;

    strobes[0] = 4'b0001;
    strobes[1] = 4'b0010;
    strobes[2] = 4'b0100;
    strobes[3] = 4'b1000;

    `uvm_info("SEQ_BYTE_LANE", $sformatf(
      "Starting individual byte-lane test on word addr=0x%08h", target_word_addr), UVM_MEDIUM)

    // Step 0: Initialize word to all zeros
    tx = axi4_seq_item::type_id::create("tx_init");
    assert(tx.randomize() with {
      is_write == 1'b1;
      ax_addr == target_word_addr;
      ax_id == trans_id;
      ax_len == 8'd0;
      ax_size == 3'b010;
      ax_burst == `BURST_INCR;
    });
    tx.w_data = 32'h0000_0000;
    tx.w_strb = 4'b1111;
    tx.w_last = 1'b1;
    start_item(tx);
    finish_item(tx);

    // Steps 1-4: Write each byte lane sequentially
    for (int lane = 0; lane < 4; lane++) begin
      bit [31:0] byte_addr = target_word_addr + lane;

      tx = axi4_seq_item::type_id::create($sformatf("tx_lane_%0d", lane));
      assert(tx.randomize() with {
        is_write == 1'b1;
        ax_addr == byte_addr;
        ax_id == trans_id;
        ax_len == 8'd0;
        ax_size == 3'b000;  // 1-byte transfer
        ax_burst == `BURST_INCR;
      });

      // Position byte data at appropriate lane
      tx.w_data = (byte_data[lane] << (lane * 8));
      tx.w_strb = strobes[lane];
      tx.w_last = 1'b1;

      `uvm_info("SEQ_BYTE_LANE", $sformatf(
        "Lane %0d: addr=0x%08h byte=0x%02h strb=4'b%04b",
        lane, byte_addr, byte_data[lane], strobes[lane]), UVM_LOW)

      start_item(tx);
      finish_item(tx);
    end

    // Step 5: Read back the full 32-bit word
    tx = axi4_seq_item::type_id::create("tx_final_read");
    assert(tx.randomize() with {
      is_write == 1'b0;
      ax_addr == target_word_addr;
      ax_id == trans_id;
      ax_len == 8'd0;
      ax_size == 3'b010;
      ax_burst == `BURST_INCR;
    });

    `uvm_info("SEQ_BYTE_LANE", "Reading back assembled 32-bit word (expect 0x44332211)", UVM_LOW)
    start_item(tx);
    finish_item(tx);

    `uvm_info("SEQ_BYTE_LANE", "Byte lane test sequence complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_BYTE_LANE_SEQ_SV

// class axi4_consecutive_oor_seq

// axi4_consecutive_oor_seq.sv
// File        : axi4_consecutive_oor_seq.sv
// Description : Consecutive out-of-range bursts sequence for TC-038.
//               Issues multiple consecutive out-of-range write and read
//               bursts to verify SLVERR response handling and that the
//               slave correctly ignores invalid addresses repeatedly.
// Author      : Verification Engineer
// Date        : 2026-09-18
// Revision    : 1.0

`ifndef AXI4_CONSECUTIVE_OOR_SEQ_SV
`define AXI4_CONSECUTIVE_OOR_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_consecutive_oor_seq extends uvm_sequence #(axi4_seq_item);

  // -----------------------------------------------------------------------
  // Configuration knobs
  // -----------------------------------------------------------------------
  rand int unsigned num_oor_transactions;
  rand bit [3:0]    trans_id;

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_object_utils(axi4_consecutive_oor_seq)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_consecutive_oor_seq");
    super.new(name);
    num_oor_transactions = 10;
    trans_id = 4'h0;
  endfunction

  // -----------------------------------------------------------------------
  // Body: Issue consecutive OOR writes and reads
  // -----------------------------------------------------------------------
  virtual task body();
    axi4_seq_item tx;
    bit [31:0] oor_addr;

    `uvm_info("SEQ_CONSEC_OOR", $sformatf(
      "Starting consecutive OOR burst sequence: %0d transactions", num_oor_transactions), UVM_MEDIUM)

    for (int i = 0; i < num_oor_transactions; i++) begin
      // Generate different out-of-range addresses
      // Base memory is 0x0000-0x0FFF (1024 words * 4 bytes)
      // OOR addresses: 0x1000, 0x2000, 0x8000, 0xFFFF_0000, etc.
      case (i % 4)
        0: oor_addr = 32'h0000_1000;
        1: oor_addr = 32'h0000_2000;
        2: oor_addr = 32'h8000_0000;
        3: oor_addr = 32'hFFFF_F000;
      endcase

      // OOR Write burst
      tx = axi4_seq_item::type_id::create($sformatf("tx_oor_write_%0d", i));
      assert(tx.randomize() with {
        is_write == 1'b1;
        ax_addr == oor_addr;
        ax_id == trans_id;
        ax_len == 8'd7;     // 8-beat burst
        ax_size == 3'b010;
        ax_burst == `BURST_INCR;
      });
      tx.w_data = 32'hDEAD_0000 | i;
      tx.w_strb = 4'b1111;
      tx.w_last = 1'b1;

      `uvm_info("SEQ_CONSEC_OOR", $sformatf(
        "OOR Write[%0d]: addr=0x%08h (expect SLVERR)", i, oor_addr), UVM_LOW)
      start_item(tx);
      finish_item(tx);

      // OOR Read burst
      tx = axi4_seq_item::type_id::create($sformatf("tx_oor_read_%0d", i));
      assert(tx.randomize() with {
        is_write == 1'b0;
        ax_addr == oor_addr;
        ax_id == trans_id;
        ax_len == 8'd7;     // 8-beat burst
        ax_size == 3'b010;
        ax_burst == `BURST_INCR;
      });

      `uvm_info("SEQ_CONSEC_OOR", $sformatf(
        "OOR Read[%0d]: addr=0x%08h (expect SLVERR)", i, oor_addr), UVM_LOW)
      start_item(tx);
      finish_item(tx);
    end

    `uvm_info("SEQ_CONSEC_OOR", "Consecutive OOR burst sequence complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_CONSECUTIVE_OOR_SEQ_SV

// class axi4_full_mem_read_seq

// axi4_full_mem_read_seq.sv
// File        : axi4_full_mem_read_seq.sv
// Description : Full memory read sweep sequence for TC-029.
//               Reads all 1024 memory words using 128 bursts of 8 words each.
//               Burst type: INCR, Size: 4 bytes (32-bit).
// Author      : Verification Engineer
// Date        : 2026-09-18
// Revision    : 1.0

`ifndef AXI4_FULL_MEM_READ_SEQ_SV
`define AXI4_FULL_MEM_READ_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_full_mem_read_seq extends uvm_sequence #(axi4_seq_item);

  // -----------------------------------------------------------------------
  // Configuration knobs
  // -----------------------------------------------------------------------
  rand bit [3:0] trans_id;

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_object_utils(axi4_full_mem_read_seq)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_full_mem_read_seq");
    super.new(name);
    trans_id = 4'h0;
  endfunction

  // -----------------------------------------------------------------------
  // Body: Read all 1024 words in 128 bursts of 8 words
  // -----------------------------------------------------------------------
  virtual task body();
    axi4_seq_item tx;
    bit [31:0] addr;
    int burst_count = 128;  // 1024 words / 8 words_per_burst = 128 bursts
    int words_per_burst = 8;
    int beats_per_burst = 8; // ax_len = 7 (0-based), so 8 beats

    `uvm_info("SEQ_FULL_MEM_R", $sformatf(
      "Starting full memory read sweep: %0d bursts x %0d words = %0d total words",
      burst_count, words_per_burst, burst_count*words_per_burst), UVM_MEDIUM)

    addr = 32'h00000000;  // Start at memory base

    for (int burst_idx = 0; burst_idx < burst_count; burst_idx++) begin
      tx = axi4_seq_item::type_id::create($sformatf("tx_burst_%0d", burst_idx));

      // Constrain burst parameters
      assert(tx.randomize() with {
        is_write == 1'b0;
        ax_addr == addr;
        ax_id == trans_id;
        ax_len == (beats_per_burst - 1);  // 7 = 8 beats (0-indexed)
        ax_size == 3'b010;                // 4 bytes (32-bit)
        ax_burst == `BURST_INCR;
        ax_lock == 1'b0;
        ax_cache == 4'b0000;
        ax_prot == 3'b000;
        ax_qos == 4'b0000;
      });

      `uvm_info("SEQ_FULL_MEM_R", $sformatf(
        "Burst[%0d/%0d]: addr=0x%08h len=%0d",
        burst_idx+1, burst_count, addr, tx.ax_len+1), UVM_LOW)

      // Send to driver
      start_item(tx);
      finish_item(tx);

      // Increment address: 8 words * 4 bytes/word = 32 bytes
      addr = addr + (words_per_burst * 4);
    end

    `uvm_info("SEQ_FULL_MEM_R", "Full memory read sweep complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_FULL_MEM_READ_SEQ_SV

// class axi4_full_mem_write_seq

// axi4_full_mem_write_seq.sv
// File        : axi4_full_mem_write_seq.sv
// Description : Full memory write sweep sequence for TC-028.
//               Writes all 1024 memory words using 128 bursts of 8 words each.
//               Burst type: INCR, Size: 4 bytes (32-bit), Pattern: incremental data.
// Author      : Verification Engineer
// Date        : 2026-09-18
// Revision    : 1.0

`ifndef AXI4_FULL_MEM_WRITE_SEQ_SV
`define AXI4_FULL_MEM_WRITE_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_full_mem_write_seq extends uvm_sequence #(axi4_seq_item);

  // -----------------------------------------------------------------------
  // Configuration knobs
  // -----------------------------------------------------------------------
  rand bit [3:0]  trans_id;
  rand bit [31:0] data_pattern_seed;

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_object_utils(axi4_full_mem_write_seq)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_full_mem_write_seq");
    super.new(name);
    trans_id = 4'h0;
    data_pattern_seed = 32'hDEAD_BEEF;
  endfunction

  // -----------------------------------------------------------------------
  // Body: Write all 1024 words in 128 bursts of 8 words
  // -----------------------------------------------------------------------
  virtual task body();
    axi4_seq_item tx;
    bit [31:0] addr;
    bit [31:0] data_val;
    int burst_count = 128;  // 1024 words / 8 words_per_burst = 128 bursts
    int words_per_burst = 8;
    int beats_per_burst = 8; // ax_len = 7 (0-based), so 8 beats

    `uvm_info("SEQ_FULL_MEM_W", $sformatf(
      "Starting full memory write sweep: %0d bursts x %0d words = %0d total words",
      burst_count, words_per_burst, burst_count*words_per_burst), UVM_MEDIUM)

    addr = 32'h00000000;  // Start at memory base
    data_val = data_pattern_seed;

    for (int burst_idx = 0; burst_idx < burst_count; burst_idx++) begin
      tx = axi4_seq_item::type_id::create($sformatf("tx_burst_%0d", burst_idx));

      // Constrain burst parameters
      assert(tx.randomize() with {
        is_write == 1'b1;
        ax_addr == addr;
        ax_id == trans_id;
        ax_len == (beats_per_burst - 1);  // 7 = 8 beats (0-indexed)
        ax_size == 3'b010;                // 4 bytes (32-bit)
        ax_burst == `BURST_INCR;
        ax_lock == 1'b0;
        ax_cache == 4'b0000;
        ax_prot == 3'b000;
        ax_qos == 4'b0000;
      });

      // Data pattern: incremental
      tx.w_data = data_val;
      tx.w_strb = 4'b1111;  // All byte lanes
      tx.w_last = 1'b1;

      `uvm_info("SEQ_FULL_MEM_W", $sformatf(
        "Burst[%0d/%0d]: addr=0x%08h data=0x%08h len=%0d",
        burst_idx+1, burst_count, addr, data_val, tx.ax_len+1), UVM_LOW)

      // Send to driver
      start_item(tx);
      finish_item(tx);

      // Increment address: 8 words * 4 bytes/word = 32 bytes
      addr = addr + (words_per_burst * 4);
      data_val = data_val + 1;
    end

    `uvm_info("SEQ_FULL_MEM_W", "Full memory write sweep complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_FULL_MEM_WRITE_SEQ_SV

// class axi4_interleaved_rw_seq

// axi4_interleaved_rw_seq.sv
// File        : axi4_interleaved_rw_seq.sv
// Description : Interleaved read/write sequence across memory for TC-035.
//               Alternates between write and read operations across
//               scattered memory addresses to stress the independent
//               FSMs and memory arbitration.
// Author      : Verification Engineer
// Date        : 2026-09-18
// Revision    : 1.0

`ifndef AXI4_INTERLEAVED_RW_SEQ_SV
`define AXI4_INTERLEAVED_RW_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_interleaved_rw_seq extends uvm_sequence #(axi4_seq_item);

  // -----------------------------------------------------------------------
  // Configuration knobs
  // -----------------------------------------------------------------------
  rand int unsigned num_pairs;
  rand bit [3:0]    trans_id;

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_object_utils(axi4_interleaved_rw_seq)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_interleaved_rw_seq");
    super.new(name);
    num_pairs = 32;
    trans_id = 4'h0;
  endfunction

  // -----------------------------------------------------------------------
  // Body: Interleave writes and reads
  // -----------------------------------------------------------------------
  virtual task body();
    axi4_seq_item w_tx;
    axi4_seq_item r_tx;
    bit [31:0] wr_addr;
    bit [31:0] rd_addr;

    `uvm_info("SEQ_INTERLEAVED", $sformatf(
      "Starting interleaved R/W sequence: %0d iterations", num_pairs), UVM_MEDIUM)

    for (int i = 0; i < num_pairs; i++) begin
      // Pick random valid word-aligned addresses
      wr_addr = (i * 32) % 4096;
      rd_addr = ((num_pairs - 1 - i) * 32) % 4096;

      // 1. Write transaction
      w_tx = axi4_seq_item::type_id::create($sformatf("w_tx_%0d", i));
      assert(w_tx.randomize() with {
        is_write == 1'b1;
        ax_addr == wr_addr;
        ax_id == trans_id;
        ax_len == 8'd3;         // 4-beat burst
        ax_size == 3'b010;      // 4 bytes
        ax_burst == `BURST_INCR;
      });
      w_tx.w_data = 32'hA000_0000 | (i << 8);
      w_tx.w_strb = 4'b1111;
      w_tx.w_last = 1'b1;

      `uvm_info("SEQ_INTERLEAVED", $sformatf(
        "Pair[%0d] Write: addr=0x%08h len=%0d", i, wr_addr, w_tx.ax_len+1), UVM_LOW)
      start_item(w_tx);
      finish_item(w_tx);

      // 2. Read transaction
      r_tx = axi4_seq_item::type_id::create($sformatf("r_tx_%0d", i));
      assert(r_tx.randomize() with {
        is_write == 1'b0;
        ax_addr == rd_addr;
        ax_id == trans_id;
        ax_len == 8'd3;         // 4-beat burst
        ax_size == 3'b010;      // 4 bytes
        ax_burst == `BURST_INCR;
      });

      `uvm_info("SEQ_INTERLEAVED", $sformatf(
        "Pair[%0d] Read: addr=0x%08h len=%0d", i, rd_addr, r_tx.ax_len+1), UVM_LOW)
      start_item(r_tx);
      finish_item(r_tx);
    end

    `uvm_info("SEQ_INTERLEAVED", "Interleaved R/W sequence complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_INTERLEAVED_RW_SEQ_SV

// class axi4_master_not_ready_seq

// axi4_master_not_ready_seq.sv
// File        : axi4_master_not_ready_seq.sv
// Description : Master not-ready sequence for AXI4 slave testbench.
//               Tests TC-014 (withhold BREADY) and TC-015 (withhold RREADY)
//               by configuring the driver to withhold handshakes.
// Author      : Verification Engineer
// Date        : 2026-09-17
// Revision    : 1.1  (fixed: THREE separate blind unconstrained
//                     tx.randomize() calls right after start_item() -
//                     withhold-BREADY branch, withhold-RREADY branch, and
//                     the "normal" write+read comparison loop - each one
//                     discarded the real constraints set moments earlier.
//                     Also tightened ax_addr to the real memory range and
//                     added WRAP-length legality.)

`ifndef AXI4_MASTER_NOT_READY_SEQ_SV
`define AXI4_MASTER_NOT_READY_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_master_not_ready_seq extends uvm_sequence #(axi4_seq_item);

  rand bit withhold_bready;   // TC-014
  rand bit withhold_rready;   // TC-015

  `uvm_object_utils(axi4_master_not_ready_seq)

  function new(string name = "axi4_master_not_ready_seq");
    super.new(name);
    withhold_bready = 1'b0;
    withhold_rready = 1'b0;
  endfunction

  virtual task pre_body();
    axi4_agent_config cfg;
    if (uvm_config_db#(axi4_agent_config)::get(null, "*", "cfg", cfg)) begin
      cfg.withhold_bready = withhold_bready;
      cfg.withhold_rready = withhold_rready;
      uvm_config_db#(axi4_agent_config)::set(null, "*", "cfg", cfg);
      `uvm_info("SEQ_MNR", $sformatf(
        "Configured withholding: bready=%0d rready=%0d",
        withhold_bready, withhold_rready), UVM_MEDIUM)
    end else begin
      `uvm_warning("SEQ_MNR", "Agent config not found in DB")
    end
  endtask

  virtual task body();
    axi4_seq_item tx;

    `uvm_info("SEQ_MNR", "Starting master not-ready sequence", UVM_MEDIUM)

    // Test write channel with withheld BREADY (TC-014)
    if (withhold_bready) begin
      tx = axi4_seq_item::type_id::create("tx_bready");
      assert(tx.randomize() with {
        is_write == 1'b1;
        ax_id    < 16;
        ax_addr  < (`C_S_AXI_MEM_DEPTH << 2);
        ax_len   < 4;
        ax_size  inside {0, 1, 2};
        ax_burst inside {`BURST_FIXED, `BURST_INCR, `BURST_WRAP};
        (ax_burst == `BURST_WRAP) -> ax_len inside {1, 3, 7, 15};
        ax_addr + ((ax_len + 1) << ax_size) <= (`C_S_AXI_MEM_DEPTH << 2);
      });
      tx.w_strb = (~0) << (tx.ax_size[1:0]);
      tx.w_last = 1'b1;

      `uvm_info("SEQ_MNR", "Sending write with withheld BREADY (TC-014)", UVM_LOW)
      start_item(tx);
      finish_item(tx);
    end

    // Test read channel with withheld RREADY (TC-015)
    if (withhold_rready) begin
      tx = axi4_seq_item::type_id::create("tx_rready");
      assert(tx.randomize() with {
        is_write == 1'b0;
        ax_id    < 16;
        ax_addr  < (`C_S_AXI_MEM_DEPTH << 2);
        ax_len   < 4;
        ax_size  inside {0, 1, 2};
        ax_burst inside {`BURST_FIXED, `BURST_INCR, `BURST_WRAP};
        (ax_burst == `BURST_WRAP) -> ax_len inside {1, 3, 7, 15};
        ax_addr + ((ax_len + 1) << ax_size) <= (`C_S_AXI_MEM_DEPTH << 2);
      });

      `uvm_info("SEQ_MNR", "Sending read with withheld RREADY (TC-015)", UVM_LOW)
      start_item(tx);
      finish_item(tx);
    end

    // Also test normal operations (no withholding) for comparison
    if (!withhold_bready && !withhold_rready) begin
      for (int i = 0; i < 5; i++) begin
        // Write
        tx = axi4_seq_item::type_id::create($sformatf("tx_w%0d", i));
        assert(tx.randomize() with {
          is_write == 1'b1;
          ax_id    < 16;
          ax_addr  < (`C_S_AXI_MEM_DEPTH << 2);
          ax_len   < 4;
          ax_size  inside {0, 1, 2};
          ax_burst inside {`BURST_FIXED, `BURST_INCR, `BURST_WRAP};
          (ax_burst == `BURST_WRAP) -> ax_len inside {1, 3, 7, 15};
          ax_addr + ((ax_len + 1) << ax_size) <= (`C_S_AXI_MEM_DEPTH << 2);
        });
        tx.w_strb = 4'hF;
        tx.w_last = 1'b1;
        start_item(tx);
        finish_item(tx);

        // Read
        tx = axi4_seq_item::type_id::create($sformatf("tx_r%0d", i));
        assert(tx.randomize() with {
          is_write == 1'b0;
          ax_id    < 16;
          ax_addr  < (`C_S_AXI_MEM_DEPTH << 2);
          ax_len   < 4;
          ax_size  inside {0, 1, 2};
          ax_burst inside {`BURST_FIXED, `BURST_INCR, `BURST_WRAP};
          (ax_burst == `BURST_WRAP) -> ax_len inside {1, 3, 7, 15};
          ax_addr + ((ax_len + 1) << ax_size) <= (`C_S_AXI_MEM_DEPTH << 2);
        });
        start_item(tx);
        finish_item(tx);
      end
    end

    `uvm_info("SEQ_MNR", "Master not-ready sequence complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_MASTER_NOT_READY_SEQ_SV

// class axi4_max_incr_seq

// axi4_max_incr_seq.sv
// File        : axi4_max_incr_seq.sv
// Description : Maximum length INCR burst sequence for TC-041.
//               Issues an INCR burst of maximum AXI4 length (ax_len = 255 -> 256 beats).
//               Tests slave beat counter, FIFO capacity, and long burst stability.
// Author      : Verification Engineer
// Date        : 2026-09-18
// Revision    : 1.0

`ifndef AXI4_MAX_INCR_SEQ_SV
`define AXI4_MAX_INCR_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_max_incr_seq extends uvm_sequence #(axi4_seq_item);

  // -----------------------------------------------------------------------
  // Configuration knobs
  // -----------------------------------------------------------------------
  rand bit [31:0] start_addr;
  rand bit [3:0]  trans_id;

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_object_utils(axi4_max_incr_seq)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_max_incr_seq");
    super.new(name);
    start_addr = 32'h0000_0000;
    trans_id = 4'h0;
  endfunction

  // -----------------------------------------------------------------------
  // Body: 256-beat INCR Write followed by 256-beat INCR Read
  // -----------------------------------------------------------------------
  virtual task body();
    axi4_seq_item tx;

    `uvm_info("SEQ_MAX_INCR", $sformatf(
      "Starting max-length INCR burst test (256 beats) at addr=0x%08h", start_addr), UVM_MEDIUM)

    // 1. Max length Write (ax_len = 255 -> 256 beats)
    tx = axi4_seq_item::type_id::create("tx_max_write");
    assert(tx.randomize() with {
      is_write == 1'b1;
      ax_addr == start_addr;
      ax_id == trans_id;
      ax_len == 8'd255;  // 256 BEATS (MAX AXI4 LENGTH)
      ax_size == 3'b010; // 4 bytes per beat -> 1024 bytes total
      ax_burst == `BURST_INCR;
      ax_lock == 1'b0;
      ax_cache == 4'b0000;
      ax_prot == 3'b000;
      ax_qos == 4'b0000;
    });

    tx.w_data = 32'hBEEF_0000;
    tx.w_strb = 4'b1111;
    tx.w_last = 1'b1;

    `uvm_info("SEQ_MAX_INCR", "Driving 256-beat INCR Write burst...", UVM_LOW)
    start_item(tx);
    finish_item(tx);

    // 2. Max length Read (ax_len = 255 -> 256 beats)
    tx = axi4_seq_item::type_id::create("tx_max_read");
    assert(tx.randomize() with {
      is_write == 1'b0;
      ax_addr == start_addr;
      ax_id == trans_id;
      ax_len == 8'd255;  // 256 BEATS (MAX AXI4 LENGTH)
      ax_size == 3'b010; // 4 bytes per beat
      ax_burst == `BURST_INCR;
      ax_lock == 1'b0;
      ax_cache == 4'b0000;
      ax_prot == 3'b000;
      ax_qos == 4'b0000;
    });

    `uvm_info("SEQ_MAX_INCR", "Driving 256-beat INCR Read burst...", UVM_LOW)
    start_item(tx);
    finish_item(tx);

    `uvm_info("SEQ_MAX_INCR", "Max-length INCR burst sequence complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_MAX_INCR_SEQ_SV

// class axi4_mem_sweep_seq

// axi4_mem_sweep_seq.sv
// File        : axi4_mem_sweep_seq.sv
// Description : Memory sweep sequence for AXI4 slave testbench.
//               Systematically sweeps through memory addresses, testing
//               memory word boundaries with incremental addresses.
// Author      : Verification Engineer
// Date        : 2026-09-17
// Revision    : 1.1  (fixed: a trailing assert(tx.randomize()) right
//                     before finish_item() re-randomized the ENTIRE item,
//                     wiping out the swept address and the preceding
//                     constrained randomize(). Removed the trailing call.)

`ifndef AXI4_MEM_SWEEP_SEQ_SV
`define AXI4_MEM_SWEEP_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_mem_sweep_seq extends uvm_sequence #(axi4_seq_item);

  rand bit [31:0] start_addr;
  rand bit [31:0] end_addr;
  rand bit [31:0] step;
  rand bit [7:0]  burst_len;
  rand bit [2:0]  burst_size;
  rand bit [1:0]  burst_type;
  rand int unsigned num_transactions;

  `uvm_object_utils(axi4_mem_sweep_seq)

  function new(string name = "axi4_mem_sweep_seq");
    super.new(name);
    start_addr = 32'h00000000;
    end_addr   = 32'h00000FFF;   // 4KB memory range
    step       = 32'h00000010;   // 16-byte step
    burst_len  = 8'd0;
    burst_size = 3'd2;
    burst_type = `BURST_INCR;
    num_transactions = 50;
  endfunction

  virtual task body();
    axi4_seq_item tx;
    bit [31:0] addr;

    `uvm_info("SEQ_SWEEP", $sformatf(
      "Starting memory sweep: start=0x%0h end=0x%0h step=0x%0h num=%0d",
      start_addr, end_addr, step, num_transactions), UVM_MEDIUM)

    addr = start_addr;
    for (int i = 0; i < num_transactions; i++) begin
      if (addr > end_addr) begin
        `uvm_info("SEQ_SWEEP", "Reached end address, wrapping to start", UVM_LOW)
        addr = start_addr;
      end

      tx = axi4_seq_item::type_id::create($sformatf("tx_%0d", i));

      assert(tx.randomize() with {
        is_write == 1'b1;
        ax_addr  == addr;
        ax_id    < 16;
        ax_len   == burst_len;
        ax_size  == burst_size;
        ax_burst == burst_type;
        ax_lock  == 1'b0;
        ax_cache == 4'b0000;
        ax_prot  == 3'b000;
      });

      tx.w_data = {8'd0, $random} & 32'hFFFFFFFF;
      tx.w_strb = (~0) << (tx.ax_size[1:0]);
      tx.w_last = 1'b1;

      `uvm_info("SEQ_SWEEP", $sformatf("Sweep[%0d]: addr=0x%0h data=0x%0h",
        i, addr, tx.w_data), UVM_LOW)

      // NOTE: removed the blind assert(tx.randomize()) that used to sit
      // here - it was wiping out the swept address every iteration.
      start_item(tx);
      finish_item(tx);

      addr = addr + step;
    end

    `uvm_info("SEQ_SWEEP", "Memory sweep complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_MEM_SWEEP_SEQ_SV

// class axi4_read_seq

// axi4_read_seq.sv
// File        : axi4_read_seq.sv
// Description : Base read sequence for AXI4 slave testbench.
//               Sends randomized read transactions with valid
//               burst types, lengths, and sizes.
// Author      : Verification Engineer
// Date        : 2026-09-17
// Revision    : 1.1  (fixed: a blind unconstrained tx.randomize() after
//                     start_item() was re-randomizing every field right
//                     before the item was sent, discarding the real
//                     constraints above it. Also: ax_addr range was
//                     1GB against a 4KB memory, so almost every
//                     transaction hit the OOR/SLVERR path instead of
//                     exercising real reads. Added WRAP-length legality
//                     constraint and a legal ax_size range.)

`ifndef AXI4_READ_SEQ_SV
`define AXI4_READ_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_read_seq extends uvm_sequence #(axi4_seq_item);

  `uvm_object_utils(axi4_read_seq)

  function new(string name = "axi4_read_seq");
    super.new(name);
  endfunction

  virtual task body();
    axi4_seq_item tx;
    int unsigned num_trans = 10;

    `uvm_info("SEQ_R", $sformatf("Starting read sequence: %0d transactions",
      num_trans), UVM_MEDIUM)

    for (int i = 0; i < num_trans; i++) begin
      tx = axi4_seq_item::type_id::create("tx");
      tx.is_write = 1'b0;

      // Single randomize call - constraints only, no second
      // unconstrained randomize afterward.
      assert(tx.randomize() with {
        ax_id    < 16;
        ax_addr  < (`C_S_AXI_MEM_DEPTH << 2);   // stay inside real memory
        ax_len   < 16;
        ax_size  inside {0, 1, 2};              // 1B/2B/4B - matches 32-bit bus
        ax_burst inside {`BURST_FIXED, `BURST_INCR, `BURST_WRAP};
        ax_lock  == 1'b0;
        ax_cache inside {4'b0000, 4'b0010, 4'b0100};
        ax_prot  inside {3'b000, 3'b001};

        // WRAP bursts must use legal lengths per AXI4 spec
        (ax_burst == `BURST_WRAP) -> ax_len inside {1, 3, 7, 15};

        // Stay inside memory for the whole burst, not just the start beat
        ax_addr + ((ax_len + 1) << ax_size) <= (`C_S_AXI_MEM_DEPTH << 2);
      });

      tx.w_last = 1'b0;

      `uvm_info("SEQ_R", $sformatf("Send read[%0d]: addr=0x%0h len=%0d size=%0d burst=%s",
        i, tx.ax_addr, tx.ax_len, tx.ax_size, tx.burst_name()), UVM_LOW)

      start_item(tx);
      finish_item(tx);
    end

    `uvm_info("SEQ_R", "Read sequence complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_READ_SEQ_SV

// class axi4_reset_during_burst_seq

// axi4_reset_during_burst_seq.sv
// File        : axi4_reset_during_burst_seq.sv
// Description : Reset during active burst sequence for TC-036/TC-037.
//               Initiates a burst transaction, then applies reset mid-burst
//               to verify DUT recovery. Configurable for write or read bursts.
// Author      : Verification Engineer
// Date        : 2026-09-18
// Revision    : 1.0

`ifndef AXI4_RESET_DURING_BURST_SEQ_SV
`define AXI4_RESET_DURING_BURST_SEQ_SV

`include "axi4_defines.svh"
`include "axi4_typedefs.svh"
`include "axi4_seq_item.sv"

class axi4_reset_during_burst_seq extends uvm_sequence #(axi4_seq_item);

  // -----------------------------------------------------------------------
  // Configuration knobs
  // -----------------------------------------------------------------------
  rand bit        is_write;
  rand bit [31:0] start_addr;
  rand bit [7:0]  burst_len;
  rand bit [3:0]  trans_id;

  // -----------------------------------------------------------------------
  // UVM factory registration
  // -----------------------------------------------------------------------
  `uvm_object_utils(axi4_reset_during_burst_seq)

  // -----------------------------------------------------------------------
  // Constructor
  // -----------------------------------------------------------------------
  function new(string name = "axi4_reset_during_burst_seq");
    super.new(name);
    is_write = 1'b1;
    start_addr = 32'h00000100;
    burst_len = 8'd15;  // 16-beat burst
    trans_id = 4'h0;
  endfunction

  // -----------------------------------------------------------------------
  // Body: Start burst, apply reset mid-transaction (via interface),
  //       then verify DUT can recover with new transaction
  // -----------------------------------------------------------------------
  virtual task body();
    axi4_seq_item tx;

    `uvm_info("SEQ_RESET_BURST", $sformatf(
      "Starting reset-during-burst test: %s burst addr=0x%08h len=%0d",
      is_write ? "WRITE" : "READ", start_addr, burst_len+1), UVM_MEDIUM)

    // Step 1: Initiate burst transaction
    tx = axi4_seq_item::type_id::create("tx_burst");
    assert(tx.randomize() with {
      is_write == local::is_write;
      ax_addr == start_addr;
      ax_id == trans_id;
      ax_len == burst_len;
      ax_size == 3'b010;
      ax_burst == `BURST_INCR;
    });

    if (is_write) begin
      tx.w_data = 32'hBAD0_0000;
      tx.w_strb = 4'b1111;
      tx.w_last = 1'b1;
    end

    `uvm_info("SEQ_RESET_BURST", "Step 1: Starting burst transaction", UVM_LOW)
    start_item(tx);

    // NOTE: Reset will be applied externally by the test at the appropriate time.
    // The sequence starts the transaction but the test is responsible for
    // triggering reset via the interface after a few beats.

    finish_item(tx);

    // Step 2: Wait for reset to complete (managed by test)
    // The test applies reset and waits for deassertion

    // Step 3: Try a new transaction to verify recovery
    tx = axi4_seq_item::type_id::create("tx_recovery");
    assert(tx.randomize() with {
      is_write == local::is_write;
      ax_addr == start_addr + 32'h40;
      ax_id == trans_id;
      ax_len == 8'd0;  // Single beat
      ax_size == 3'b010;
      ax_burst == `BURST_INCR;
    });

    if (is_write) begin
      tx.w_data = 32'hC0DE_0001;
      tx.w_strb = 4'b1111;
      tx.w_last = 1'b1;
    end

    `uvm_info("SEQ_RESET_BURST", "Step 3: Attempting recovery transaction post-reset", UVM_LOW)
    start_item(tx);
    finish_item(tx);

    `uvm_info("SEQ_RESET_BURST", "Reset-during-burst sequence complete", UVM_MEDIUM)
  endtask

endclass

`endif // AXI4_RESET_DURING_BURST_SEQ_SV

